function qianchuanPlanAttachErrorText(error) {
  return String(error?.message || error?.stack || error || "");
}

function isRecoverableQianchuanPlanAttachError(error) {
  const text = qianchuanPlanAttachErrorText(error);
  return /image_ids|image_material|programmatic_creative_media_list|素材.*检测|素材检测|10026|permission|grant you|role is wrong|计划读取/.test(text);
}

function qianchuanPlanAttachWarning(error) {
  const text = qianchuanPlanAttachErrorText(error);
  if (/image_ids|image_material|programmatic_creative_media_list/.test(text)) {
    return "视频已上传到千川素材库；当前千川计划关联接口还要求封面图片素材ID，工作站已保留目标计划信息，可先在千川后台选择该素材，或稍后补齐封面后再关联。";
  }
  if (/素材.*检测|素材检测|10026/.test(text)) {
    return "视频已上传到千川素材库；千川素材合规检测仍在排队，工作站已保留素材ID，稍后可重试关联计划。";
  }
  if (/permission|grant you|role is wrong|计划读取/.test(text)) {
    return "视频已上传到千川素材库；当前账号没有该计划的读取或关联权限，工作站已保留素材ID，请换有权限的账号或在千川后台人工关联。";
  }
  return "视频已上传到千川素材库；计划关联未完成，工作站已保留素材ID，可稍后重试或在千川后台人工关联。";
}

