function normalizeProductVideoDuration(value, fallback = PRODUCT_VIDEO_MIN_DURATION) {
  const requested = Number(value);
  const safeFallback = Number.isFinite(Number(fallback)) ? Number(fallback) : PRODUCT_VIDEO_MIN_DURATION;
  const normalized = Number.isFinite(requested) ? requested : safeFallback;
  return Math.max(PRODUCT_VIDEO_MIN_DURATION, Math.min(PRODUCT_VIDEO_MAX_DURATION, Math.round(normalized)));
}

