function resolveMediaTool(name) {
  const executable = process.platform === "win32" ? `${name}.exe` : name;
  const environmentPath = name === "ffmpeg" ? process.env.FFMPEG_PATH : process.env.FFPROBE_PATH;
  const installerPlatform = `${process.platform}-${process.arch}`;
  const candidates = [
    environmentPath,
    path.join(PACKAGE_ROOT, "tools", executable),
    name === "ffmpeg"
      ? path.join(MEDIA_RUNTIME_ROOT, "node_modules", "@ffmpeg-installer", installerPlatform, executable)
      : path.join(MEDIA_RUNTIME_ROOT, "node_modules", "@ffprobe-installer", installerPlatform, executable),
    name === "ffmpeg"
      ? path.join(MEDIA_RUNTIME_ROOT, "node_modules", "ffmpeg-static", executable)
      : path.join(MEDIA_RUNTIME_ROOT, "node_modules", "ffprobe-static", "bin", process.platform === "win32" ? "win32" : process.platform, process.arch === "x64" ? "x64" : process.arch, executable)
  ].filter(Boolean);
  const existing = candidates.find((candidate) => fs.existsSync(candidate));
  if (existing) return existing;
  const finder = process.platform === "win32" ? "where.exe" : "which";
  const located = spawnSync(finder, [name], { windowsHide: true, encoding: "utf8" });
  if (located.status === 0) {
    return String(located.stdout || "").split(/\r?\n/).map((item) => item.trim()).find(Boolean) || name;
  }
  return name;
}

