function detectPackageRoot(appRoot) {
  const parent = path.resolve(appRoot, "..");
  const packageMarkers = ["runtime", "tools", "updates", "AI视频工作台.exe", "产品镜生成器.exe"];
  return packageMarkers.some((name) => fs.existsSync(path.join(parent, name))) ? parent : appRoot;
}

function readLocalPackage() {
  try {
    return JSON.parse(fs.readFileSync(PACKAGE_JSON_PATH, "utf8").replace(/^\uFEFF/, ""));
  } catch {
    return {};
  }
}

