function readJsonFile(filePath) {
  try {
    return JSON.parse(fs.readFileSync(filePath, "utf8").replace(/^\uFEFF/, ""));
  } catch {
    return null;
  }
}

function uniquePaths(paths) {
  return [...new Set(paths.map((item) => path.resolve(item)))];
}

function resolvePluginPath(value, pluginDir) {
  const text = String(value || "").trim();
  if (!text || isHttpReference(text)) return text;
  return path.isAbsolute(text) ? text : path.resolve(pluginDir, text);
}

function flattenPromptStrategy(product) {
  const strategy = product?.promptStrategy || product?.prompt || {};
  const coreScenes = product?.coreScenes || product?.sceneCores || strategy.coreScenes || strategy.sceneCores;
  return {
    ...product,
    ...strategy,
    coreScenes
  };
}

function normalizePluginProduct(rawProduct, pluginDir, pluginMeta) {
  const product = flattenPromptStrategy(rawProduct || {});
  if (!product.id || !product.name) return null;
  if (product.imageDir) product.imageDir = resolvePluginPath(product.imageDir, pluginDir);
  if (!Array.isArray(product.imagePriority)) product.imagePriority = [];
  return {
    ...product,
    pluginId: pluginMeta.pluginId,
    pluginVersion: pluginMeta.version,
    source: "plugin"
  };
}

function pluginManifestPath(pluginDir) {
  return PRODUCT_PLUGIN_MANIFEST_FILES
    .map((file) => path.join(pluginDir, file))
    .find((filePath) => fs.existsSync(filePath)) || "";
}

function readProductPlugin(pluginDir) {
  const manifestPath = pluginManifestPath(pluginDir);
  if (!manifestPath) return null;
  const data = readJsonFile(manifestPath);
  if (!data) return null;
  const rawProducts = Array.isArray(data)
    ? data
    : Array.isArray(data.products)
      ? data.products
      : data.product
        ? [data.product]
        : [];
  const pluginMeta = {
    pluginId: String(data.pluginId || data.id || path.basename(pluginDir)),
    name: String(data.name || path.basename(pluginDir)),
    version: String(data.version || "0.0.0"),
    path: pluginDir,
    manifestPath
  };
  const products = rawProducts
    .map((product) => normalizePluginProduct(product, pluginDir, pluginMeta))
    .filter(Boolean);
  return { ...pluginMeta, productCount: products.length, products };
}

function loadProductCatalog() {
  const products = new Map(BASE_PRODUCTS.map((product) => [product.id, { ...product, source: "built-in" }]));
  const plugins = [];
  for (const rootDir of uniquePaths([APP_PRODUCT_PLUGIN_DIR, PRODUCT_PLUGIN_DIR])) {
    if (!fs.existsSync(rootDir)) continue;
    let entries = [];
    try {
      entries = fs.readdirSync(rootDir, { withFileTypes: true });
    } catch {
      continue;
    }
    const pluginDirs = entries
      .filter((entry) => entry.isDirectory())
      .map((entry) => path.join(rootDir, entry.name));
    if (pluginManifestPath(rootDir)) pluginDirs.unshift(rootDir);
    for (const pluginDir of uniquePaths(pluginDirs)) {
      const plugin = readProductPlugin(pluginDir);
      if (!plugin) continue;
      plugins.push({
        pluginId: plugin.pluginId,
        name: plugin.name,
        version: plugin.version,
        productCount: plugin.productCount,
        path: plugin.path
      });
      for (const pluginProduct of plugin.products) {
        products.set(pluginProduct.id, {
          ...(products.get(pluginProduct.id) || {}),
          ...pluginProduct
        });
      }
    }
  }
  return {
    products: Array.from(products.values()).map((product) => {
      const profile = productProfile(product.id);
      return {
        ...product,
        ...(profile ? {
          name: profile.platformName,
          shortName: profile.shortName,
          productProfile: { schemaVersion: PRODUCT_PROFILE_SCHEMA_VERSION, ...profile }
        } : {}),
        replacementContract: productReplacementContract(product)
      };
    }),
    plugins
  };
}

function getProducts() {
  return loadProductCatalog().products.filter(isVisibleProduct);
}

function getProductPlugins() {
  return loadProductCatalog().plugins;
}

