async function writeSourceTranscriptAudit(result, outputDir, basename = "source-transcript") {
  if (!outputDir) return "";
  await fsp.mkdir(outputDir, { recursive: true });
  const auditPath = path.join(outputDir, `${safeName(basename, "source-transcript")}.json`);
  await fsp.writeFile(auditPath, JSON.stringify(result, null, 2), "utf8");
  return auditPath;
}

async function probeSourceAudioTopology(videoPath) {
  const result = await runProcess(FFPROBE, [
    "-v", "error",
    "-select_streams", "a:0",
    "-show_entries", "stream=codec_name,sample_rate,channels,channel_layout:format=duration",
    "-of", "json",
    videoPath
  ]);
  if (result.code !== 0) throw new Error(`无法读取参考视频音轨：${result.stderr || result.stdout}`);
  const parsed = tryParseJson(result.stdout) || {};
  const stream = Array.isArray(parsed.streams) ? parsed.streams[0] : null;
  if (!stream) throw new Error("参考视频没有可用音轨");
  return {
    codec: String(stream.codec_name || ""),
    sampleRate: Math.max(0, Number(stream.sample_rate || 0)),
    channels: Math.max(0, Number(stream.channels || 0)),
    channelLayout: String(stream.channel_layout || ""),
    duration: Math.max(0, Number(parsed?.format?.duration || 0))
  };
}

async function extractSourcePcm(videoPath, outputPath, mode) {
  const args = ["-y", "-i", videoPath, "-map", "0:a:0", "-vn"];
  if (mode === "stereo") args.push("-ac", "2");
  else if (mode === "left") args.push("-af", "pan=mono|c0=c0");
  else if (mode === "right") args.push("-af", "pan=mono|c0=c1");
  else args.push("-ac", "1");
  args.push("-ar", "16000", "-c:a", "pcm_s16le", outputPath);
  const extracted = await runProcess(FFMPEG, args);
  if (extracted.code !== 0 || !fs.existsSync(outputPath)) {
    throw new Error(`参考视频口播音轨提取失败：${extracted.stderr || extracted.stdout || "没有可用音轨"}`);
  }
  return outputPath;
}

async function transcribeSourceVideo(input = {}) {
  await ensureRemixMediaTools();
  const videoPath = path.resolve(String(input.videoPath || input.referenceVideoPath || ""));
  const stat = await fsp.stat(videoPath).catch(() => null);
  if (!stat?.isFile() || !VIDEO_FILE_PATTERN.test(videoPath)) throw new Error("待转写参考视频不存在或格式不支持");
  const sourceSha256 = await hashFile(videoPath);
  const modelTag = safeName(deepseekTranscriptClient.status().model || "deepseek", "deepseek");
  const asrModelTag = safeName(xingChenAsrClient.status().model || "xingchen-asr", "xingchen-asr");
  const cachePath = path.join(SOURCE_TRANSCRIPT_CACHE_DIR, `${sourceSha256}-${asrModelTag}-${modelTag}-v${SOURCE_TRANSCRIPT_CACHE_VERSION}.json`);
  if (input.force !== true) {
    try {
      const cached = JSON.parse(await fsp.readFile(cachePath, "utf8"));
      if (cached?.schemaVersion === "source-transcript-v3" && cached.text) {
        const result = { ...cached, cacheHit: true };
        result.auditPath = await writeSourceTranscriptAudit(result, input.outputDir, input.auditName);
        return result;
      }
    } catch {}
  }
  await fsp.mkdir(SOURCE_TRANSCRIPT_CACHE_DIR, { recursive: true });
  const derivativeId = crypto.randomUUID();
  const derivativeBase = path.join(SOURCE_TRANSCRIPT_CACHE_DIR, `${sourceSha256}-${derivativeId}`);
  const audioPath = `${derivativeBase}-mono.wav`;
  const stereoPath = `${derivativeBase}-stereo.wav`;
  const leftPath = `${derivativeBase}-left.wav`;
  const rightPath = `${derivativeBase}-right.wav`;
  const derivatives = [audioPath, stereoPath, leftPath, rightPath];
  try {
    const audioTopology = await probeSourceAudioTopology(videoPath);
    await extractSourcePcm(videoPath, audioPath, "mono");
    const monoAsrResult = await xingChenAsrClient.transcribeFile(audioPath);
    monoAsrResult.segments = markOverlappingSegments(monoAsrResult.segments);
    monoAsrResult.channelStrategy = "mono_diarize";
    monoAsrResult.audioTopology = audioTopology;
    let asrResult = monoAsrResult;
    let channelDecision = {
      strategy: "mono_diarize",
      reason: audioTopology.channels === 2 ? "等待左右声道差异检测" : "非标准双声道，使用单声道Diarize",
      sourceChannels: audioTopology.channels,
      channelLayout: audioTopology.channelLayout
    };
    if (audioTopology.channels === 2) {
      await extractSourcePcm(videoPath, stereoPath, "stereo");
      const stereoAnalysis = analyzePcm16StereoWav(await fsp.readFile(stereoPath));
      const splitCandidate = assessStereoSplitCandidate(stereoAnalysis);
      channelDecision = {
        ...channelDecision,
        ...splitCandidate,
        analysis: stereoAnalysis
      };
      if (splitCandidate.candidate) {
        await Promise.all([
          extractSourcePcm(videoPath, leftPath, "left"),
          extractSourcePcm(videoPath, rightPath, "right")
        ]);
        const [leftAsrResult, rightAsrResult] = await Promise.all([
          xingChenAsrClient.transcribeFile(leftPath),
          xingChenAsrClient.transcribeFile(rightPath)
        ]);
        const merged = mergeIndependentChannelTranscripts(leftAsrResult, rightAsrResult);
        channelDecision = {
          ...channelDecision,
          strategy: merged.accepted ? "split_stereo" : "mono_diarize",
          reason: merged.reason,
          textSimilarity: Number.isFinite(merged.textSimilarity) ? merged.textSimilarity : null
        };
        if (merged.accepted) asrResult = merged;
      }
    }
    asrResult.audioTopology = audioTopology;
    asrResult.channelDecision = channelDecision;
    if (!String(asrResult?.text || "").trim()) throw new Error("XingChenASR没有识别到可用口播");
    const refined = await sourceTranscriptRefiner.refine(asrResult, {
      workflow: String(input.workflow || "视频工作台")
    });
    const result = {
      ...assembleSourceTranscript(asrResult, refined),
      sourceSha256,
      transcribedAt: new Date().toISOString(),
      cacheHit: false
    };
    await fsp.writeFile(cachePath, JSON.stringify(result, null, 2), "utf8");
    result.auditPath = await writeSourceTranscriptAudit(result, input.outputDir, input.auditName);
    return result;
  } finally {
    await Promise.all(derivatives.map((filePath) => fsp.rm(filePath, { force: true }).catch(() => {})));
  }
}

