function hydrateOneClickRemakeProduct(product = {}) {
  const profile = product.source === "custom" ? customProductProfile(product) : productProfile(product.id);
  const customDefaults = product.source === "custom" ? {
    spokenName: product.shortName || product.name,
    imageDir: "",
    imagePriority: [],
    defaultPurpose: "产品展示",
    defaultScene: "真实生活场景",
    visualIdentity: `${product.name || "该产品"}的外观必须严格服从用户上传并审核的 OSS 产品资产`,
    benefitCues: "仅展示用户已提供并确认的产品信息，不推断未提供的功效或规格",
    compliance: "不得虚构功效、规格、包装文字、数量、结构或使用方式",
    negativeExtra: "错误SKU，虚构包装，虚构规格，虚构功效，新增产品文字",
    commerce: { unitSpec: "", offers: [] }
  } : {};
  const hydrated = {
    ...product,
    ...customDefaults,
    ...(profile ? {
      name: profile.platformName || product.name,
      shortName: profile.shortName || product.shortName || product.name,
      productProfile: { schemaVersion: PRODUCT_PROFILE_SCHEMA_VERSION, ...profile }
    } : {})
  };
  return {
    ...hydrated,
    replacementContract: productReplacementContract(hydrated)
  };
}

function customProductProfile(product = {}) {
  if (product.source !== "custom") return null;
  const stateId = String(product.defaultProductState || "").trim();
  const dimensionsCm = product.dimensionsCm && typeof product.dimensionsCm === "object" ? product.dimensionsCm : {};
  const remakeDimensionsCm = stateId === "retail_outer_box" && dimensionsCm.width
    ? { ...dimensionsCm, depth: dimensionsCm.width }
    : dimensionsCm;
  const dimensionsByState = {
    retail_outer_box: { retailOuterBox: dimensionsCm },
    primary_container: { primaryContainer: dimensionsCm },
    single_unit: { singleSachet: dimensionsCm },
    content: { content: dimensionsCm },
    open_state: {},
    usage_state: {},
    product_combination: {}
  };
  return {
    platformName: product.name,
    shortName: product.shortName || product.name,
    category: product.category || "custom",
    packageHierarchy: stateId ? [stateId] : [],
    remakeDefaultStateId: stateId,
    remakeStates: stateId ? [{
      id: stateId,
      dimensionsCm: remakeDimensionsCm,
      allowedActions: ["陈列", "手持"],
      forbiddenActions: ["擅自改变包装结构", "虚构开合、出液或使用动作"]
    }] : [],
    dimensionsCm: dimensionsByState[stateId] || {},
    usage: "仅按用户上传并审核的产品资产展示，不推断未提供的包装结构、功效或使用动作"
  };
}

function getPlatformProducts() {
  const merged = new Map((getProducts() || []).filter((product) => product?.id).map((product) => [String(product.id), product]));
  for (const managed of productWorkflows.catalogProducts()) {
    const id = String(managed.id || "");
    if (!id) continue;
    const combined = { ...(merged.get(id) || {}), ...managed, id };
    merged.set(id, hydrateOneClickRemakeProduct(combined));
  }
  return [...merged.values()].filter(isVisibleProduct);
}

function getOneClickRemakeProducts() {
  return mergeRemakeProductCatalog(
    getProducts(),
    productWorkflows.catalogProducts(),
    hydrateOneClickRemakeProduct
  ).filter(isVisibleProduct);
}

async function extractOneClickRemakeSourceProductFrames(input = {}) {
  const videoUrl = String(input.videoUrl || "").trim();
  if (!/^https?:\/\//i.test(videoUrl)) throw new Error("原视频缺少可下载地址，无法执行视觉 SKU 推荐");
  await ensureRemixMediaTools();
  const outputDir = path.resolve(String(input.outputDir || path.join(DEFAULT_OUTPUT_DIR, "一键做同款", String(input.jobId || "unknown"), "source-product-visual")));
  await fsp.mkdir(outputDir, { recursive: true });
  const videoPath = path.join(outputDir, "source-result-video.mp4");
  const videoStat = await fsp.stat(videoPath).catch(() => null);
  if (!videoStat?.isFile() || videoStat.size === 0) await downloadFile(videoUrl, videoPath);
  const probe = await runProcess(FFPROBE, [
    "-v", "error",
    "-show_entries", "format=duration:stream=codec_type",
    "-of", "json",
    videoPath
  ]);
  if (probe.code !== 0) throw new Error(`无法读取原视频时长：${probe.stderr || probe.stdout}`);
  const metadata = tryParseJson(probe.stdout) || {};
  const duration = Number(metadata?.format?.duration || 0);
  if (!(duration > 0.2)) throw new Error("原视频没有可用于识别的有效时长");
  const frames = await extractReplacementAnalysisFrames(videoPath, path.join(outputDir, "keyframes"), duration);
  const selected = frames.length <= 8
    ? frames
    : Array.from({ length: 8 }, (_, index) => frames[Math.round(index * (frames.length - 1) / 7)]);
  return Promise.all(selected.map(async (frame) => ({
    id: frame.id,
    time: frame.time,
    dataUrl: `data:image/jpeg;base64,${(await fsp.readFile(frame.localPath)).toString("base64")}`
  })));
}

