function resolveAiShowcaseVideoModel(value = "") {
  const requested = String(value || "").trim();
  const selected = AI_SHOWCASE_VIDEO_MODELS.find((model) => model.id === requested || model.label === requested)
    || (!requested ? AI_SHOWCASE_VIDEO_MODELS[0] : null);
  if (!selected) throw new Error("视频生成模型仅支持 Seedance 2.0 VIP、Seedance 2.5 或 Kling O3");
  return selected;
}

function resolveAiShowcaseVideoGenerationMode(videoModelValue, value = "", options = {}) {
  const videoModel = typeof videoModelValue === "object" && videoModelValue
    ? videoModelValue
    : resolveAiShowcaseVideoModel(videoModelValue);
  const modes = Array.isArray(videoModel.videoGenerationModes) ? videoModel.videoGenerationModes : [];
  const requested = String(value || "").trim();
  const selected = modes.find((mode) => mode.value === requested || mode.label === requested);
  if (selected) return selected;
  if (requested && options.fallbackToDefault !== true) {
    const supported = modes.map((mode) => mode.label).join("、");
    const error = new Error(`${videoModel.label} 不支持该视频生成模式，可选：${supported}`);
    error.code = "VIDEO_GENERATION_MODE_UNSUPPORTED";
    error.statusCode = 400;
    throw error;
  }
  return modes.find((mode) => mode.value === videoModel.defaultVideoGenerationMode)
    || modes[0]
    || AI_SHOWCASE_VIDEO_GENERATION_MODES.mixed2video;
}

function aiShowcaseVideoModeUsesAutomaticGeometry(videoModel, videoGenerationMode, actualModelLabel = "") {
  return videoModel?.id === "seedance-2-5"
    && String(actualModelLabel || videoModel.label || "").trim() === "Seedance 2.5"
    && videoGenerationMode?.value === "videoEdit2video";
}

function resolveAiShowcasePromptTemplateForVideoSelection(videoModelValue, videoGenerationModeValue) {
  const videoModel = typeof videoModelValue === "object" && videoModelValue
    ? videoModelValue
    : resolveAiShowcaseVideoModel(videoModelValue);
  const videoGenerationMode = typeof videoGenerationModeValue === "object" && videoGenerationModeValue
    ? videoGenerationModeValue
    : resolveAiShowcaseVideoGenerationMode(videoModel, videoGenerationModeValue);
  if (["seedance-2-vip", "seedance-2-5"].includes(videoModel.id) && videoGenerationMode.value === "mixed2video") {
    return AI_SHOWCASE_PROMPT_TEMPLATE_ID;
  }
  if (videoModel.id === "seedance-2-5" && videoGenerationMode.value === "videoEdit2video") {
    return CUSTOM_CREATIVE_PROMPT_TEMPLATE_ID;
  }
  const error = new Error(`${videoModel.label} · ${videoGenerationMode.label} 的AI产品镜提示词模板尚未开放`);
  error.code = "AI_SHOWCASE_PROMPT_TEMPLATE_UNAVAILABLE";
  error.statusCode = 400;
  throw error;
}

function sceneVideoModelsForConfig(config = {}, hasSourceVideo = false) {
  const presets = hasSourceVideo ? SOURCE_VIDEO_MODEL_PRESETS : MODEL_PRESETS;
  const configured = presets[config.modelMode] || presets.auto;
  if (config.customCreativeOutput === true && config.capacityFallbackModels === true) {
    return presets.auto.filter((model) => CUSTOM_CREATIVE_CAPACITY_FALLBACK_MODELS.includes(model.label));
  }
  return config.fallbackModels === false ? configured.slice(0, 1) : configured;
}

