function productCanvasDate(value = new Date()) {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: "Asia/Shanghai",
    year: "numeric",
    month: "2-digit",
    day: "2-digit"
  }).formatToParts(new Date(value));
  const read = (type) => parts.find((part) => part.type === type)?.value || "";
  return `${read("year")}-${read("month")}-${read("day")}`;
}

function productCanvasClock(value = new Date()) {
  const parts = new Intl.DateTimeFormat("zh-CN", {
    timeZone: "Asia/Shanghai",
    hour12: false,
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit"
  }).formatToParts(new Date(value));
  const read = (type) => parts.find((part) => part.type === type)?.value || "00";
  return `${read("hour")}${read("minute")}${read("second")}`;
}

function normalizeWorkbenchDevice(input = {}) {
  const rawId = String(input.workstationId || input.id || "").trim().toLowerCase();
  const workstationId = rawId.replace(/[^a-z0-9-]/g, "").slice(0, 80);
  const compactId = workstationId.replace(/[^a-z0-9]/g, "");
  if (compactId.length < 16) {
    throw new Error("当前页面缺少本机工作台标识，请刷新页面后重新提交");
  }
  const shortId = compactId.slice(-8).toUpperCase();
  const requestedLabel = String(input.workstationLabel || input.label || "").trim();
  const safeLabel = requestedLabel ? safeName(requestedLabel).slice(0, 22) : "电脑";
  const workstationLabel = safeLabel.toUpperCase().includes(shortId) ? safeLabel : `${safeLabel}-${shortId}`;
  return { workstationId, workstationLabel, shortId };
}

function normalizeWorkbenchDeviceForRequest(input = {}) {
  try {
    return normalizeWorkbenchDevice(input);
  } catch (error) {
    const ownerKey = String(currentLibtvUserScope()?.key || "").trim();
    const provided = String(input.workstationId || input.id || "").trim();
    if (provided || !ownerKey) throw error;
    const legacyId = crypto.createHash("sha256").update(`legacy-workstation:${ownerKey}`).digest("hex").slice(0, 32);
    return normalizeWorkbenchDevice({ workstationId: legacyId, workstationLabel: "电脑-兼容" });
  }
}

function productDailyCanvasName(date) {
  return `${date}_AI产品镜生成`;
}

function libtvActiveAccountScope(account = {}) {
  const active = account?.activeAccount || {};
  const user = account?.user || {};
  const rawTeamId = Number(account?.teamId || 0);
  const rawIdentity = [
    active.accountId,
    active.ownerUuid,
    active.accountName,
    user.uuid,
    user.id
  ].filter((value) => value !== undefined && value !== null && String(value).trim()).join("|") || "active-account";
  return {
    accountKey: crypto.createHash("sha1").update(rawIdentity).digest("hex").slice(0, 16),
    accountId: String(active.accountId || "").trim(),
    accountName: String(active.accountName || "").trim(),
    accountType: Number(active.accountType || 0),
    teamId: Number.isFinite(rawTeamId) ? Math.max(0, Math.trunc(rawTeamId)) : 0
  };
}

function productDailyCanvasKey(date, device, accountScope = {}) {
  const ownerKey = String(accountScope.ownerKey || accountScope.workbenchOwnerKey || "anonymous").trim().toLowerCase();
  return ["ai-product-showcase-v2", date, ownerKey, accountScope.accountKey, `team-${accountScope.teamId || 0}`].join("|");
}

function sceneVideoNodeNamespace(job) {
  if (job.nodeNamespace) return job.nodeNamespace;
  const clock = productCanvasClock(job.createdAt || new Date());
  const token = crypto.createHash("sha1").update(String(job.id || `${clock}-${Math.random()}`)).digest("hex").slice(0, 6).toUpperCase();
  job.nodeNamespace = `任务-${clock}-${token}`;
  return job.nodeNamespace;
}

function sceneVideoNodeName(job, label) {
  return safeName(`${sceneVideoNodeNamespace(job)}-${label}`).slice(0, 80);
}

function sceneVideoCanvasSlot(job) {
  if (Number.isInteger(job.canvasTaskSlot) && job.canvasTaskSlot >= 0) return job.canvasTaskSlot;
  const date = productCanvasDate(job.createdAt || new Date());
  const dailyCanvasKey = String(job.dailyCanvasKey || "");
  const ownerKey = String(job.libtvOwner?.key || "");
  const related = [...jobs.values()]
    .filter((item) => item.config?.canvasMode === "device-daily")
    .filter((item) => dailyCanvasKey
      ? String(item.dailyCanvasKey || "") === dailyCanvasKey
      : String(item.libtvOwner?.key || "") === ownerKey)
    .filter((item) => productCanvasDate(item.createdAt || new Date()) === date)
    .sort((left, right) => String(left.createdAt || "").localeCompare(String(right.createdAt || "")) || String(left.id).localeCompare(String(right.id)));
  const usedSlots = related
    .filter((item) => item.id !== job.id && Number.isInteger(item.canvasTaskSlot) && item.canvasTaskSlot >= 0)
    .map((item) => item.canvasTaskSlot);
  const indexedSlot = related.findIndex((item) => item.id === job.id);
  let nextSlot = Math.max(0, indexedSlot);
  while (usedSlots.includes(nextSlot)) nextSlot += 1;
  job.canvasTaskSlot = nextSlot;
  return job.canvasTaskSlot;
}

function sceneVideoCanvasOrigin(job) {
  if (job.config?.canvasMode === "device-daily" && Number(job.dailyWorkspaceId || 0) > 0) {
    return { x: 0, y: 0 };
  }
  if (job.config?.canvasMode === "workbench-task-v2") {
    const slot = Math.max(0, Math.trunc(Number(job.canvasTaskSlot || 0) || 0));
    return {
      x: (slot % 4) * 3600,
      y: Math.floor(slot / 4) * 1800
    };
  }
  const slot = sceneVideoCanvasSlot(job);
  return {
    x: (slot % 4) * 3600,
    y: Math.floor(slot / 4) * 1800
  };
}

function resolveProduct(config = {}) {
  const productId = String(config.productId || "");
  const productType = String(config.productType || "");
  const products = getPlatformProducts();
  const matched = products.find((product) => product.id === productId || product.name === productType);
  if (matched) return matched;
  if (config.allowCustomProduct === true && productType) {
    const customProductAssets = Array.isArray(config.productAssetPaths)
      ? config.productAssetPaths.map((item) => String(item || "").trim()).filter(Boolean)
      : [];
    return {
      id: productId || `custom-${crypto.createHash("sha1").update(productType).digest("hex").slice(0, 10)}`,
      name: productType,
      shortName: productType,
      spokenName: productType,
      category: "custom",
      imageDir: customProductAssets.length ? path.dirname(path.resolve(customProductAssets[0])) : DEFAULT_IMAGE_DIR,
      imagePriority: [],
      defaultPurpose: "产品展示",
      defaultScene: "真实生活场景",
      visualIdentity: `${productType}的输入产品图真值`,
      benefitCues: "仅展示已经由用户提供并确认的产品外观，不推测未提供的功效和规格",
      negativeExtra: "错误SKU，虚构包装，虚构规格，虚构功效，新增产品文字"
    };
  }
  return products[0] || BASE_PRODUCTS[0];
}

function isKnownProductImageDir(imageDir) {
  if (!imageDir) return false;
  const normalized = path.resolve(String(imageDir)).toLowerCase();
  return getProducts().some((product) => path.resolve(product.imageDir).toLowerCase() === normalized);
}

async function approvedServedMediaPath(candidate) {
  if (process.env.LOCAL_SIMULATION === '1' && currentLibtvUserScope()) {
    const scope = currentLibtvUserScope();
    const realCandidate = await fsp.realpath(path.resolve(String(candidate || ""))).catch(() => "");
    const outputRoots = [DEFAULT_OUTPUT_DIR, KOC_OUTPUT_DIR, VARIATION_OUTPUT_DIR];
    if (realCandidate && outputRoots.some(root => isPathInside(root, realCandidate))) {
      const owned = await Promise.all([...jobs.values()].filter(job => job.libtvOwner?.key === scope.key && job.outputDir)
        .map(async job => {
          const realRoot = await fsp.realpath(job.outputDir).catch(() => "");
          return Boolean(realRoot && isPathInside(realRoot, realCandidate));
        }));
      if (!owned.some(Boolean)) return null;
    }
  }
  return resolveServedMediaPath(candidate, [
    UPLOADS_DIR,
    DEFAULT_OUTPUT_DIR,
    ...getProducts().map((product) => product.imageDir).filter(Boolean)
  ]);
}

function productForImageDir(imageDir) {
  if (!imageDir) return null;
  const normalized = path.resolve(String(imageDir)).toLowerCase();
  return getProducts().find((product) => path.resolve(product.imageDir).toLowerCase() === normalized) || null;
}

function remapLegacyPackagePath(value) {
  const text = String(value || "").trim();
  if (!text) return "";
  const normalized = text.replace(/\//g, "\\");
  const marker = "\\产品镜生成器\\";
  const markerIndex = normalized.toLowerCase().indexOf(marker.toLowerCase());
  if (markerIndex < 0) return text;
  const relativePart = normalized.slice(markerIndex + marker.length);
  return path.resolve(PACKAGE_ROOT, relativePart);
}

function remapLegacyJobPaths(value, key = "") {
  if (Array.isArray(value)) return value.map((item) => remapLegacyJobPaths(item, key));
  if (value && typeof value === "object") {
    return Object.fromEntries(Object.entries(value).map(([childKey, child]) => [
      childKey,
      remapLegacyJobPaths(child, childKey)
    ]));
  }
  if (typeof value === "string" && /(path|dir)$/i.test(key)) {
    return remapLegacyPackagePath(value);
  }
  return value;
}

function normalizeJobConfig(config = {}) {
  const product = resolveProduct(config);
  const generationMode = config.generationMode === "scene-video" ? "scene-video" : "product-images";
  const emotionHook = PRODUCT_EMOTION_HOOKS[config.emotionHook] ? config.emotionHook : DEFAULTS.emotionHook;
  const sourceVideoPaths = Array.isArray(config.sourceVideoPaths)
    ? config.sourceVideoPaths.map((item) => String(item || "").trim()).filter(Boolean)
    : [];
  const sourceVideoNames = Array.isArray(config.sourceVideoNames)
    ? config.sourceVideoNames.map((item) => String(item || "").trim())
    : [];
  return {
    ...DEFAULTS,
    ...config,
    generationMode,
    productId: product.id,
    productType: product.name,
    purpose: config.purpose || product.defaultPurpose || DEFAULTS.purpose,
    emotionHook,
    scene: config.scene || product.defaultScene || DEFAULTS.scene,
    // A selected product always owns its asset directory. Older clients persisted an
    // absolute path under "产品镜生成器", which becomes invalid after an online update.
    imageDir: product.imageDir,
    outputDir: remapLegacyPackagePath(config.outputDir) || DEFAULTS.outputDir,
    libtvUrl: String(config.libtvUrl || DEFAULTS.libtvUrl).trim(),
    sceneImagePath: String(config.sceneImagePath || "").trim(),
    sceneImageName: String(config.sceneImageName || "").trim(),
    sourceVideoPath: String(config.sourceVideoPath || "").trim(),
    sourceVideoPaths,
    sourceVideoNames,
    combineSourceVideos: config.combineSourceVideos === true,
    combinedSourceVideoName: String(config.combinedSourceVideoName || "").trim(),
    canvasMode: ["device-daily", "workbench-task-v2"].includes(config.canvasMode) ? config.canvasMode : "per-job",
    workstationId: String(config.workstationId || "").trim().toLowerCase(),
    workstationLabel: String(config.workstationLabel || "").trim(),
    modelMode: generationMode === "scene-video" && config.modelMode === "lite" ? "auto" : (config.modelMode || DEFAULTS.modelMode)
  };
}

