function buildMixedReferenceVideoPrompt(config = {}) {
  if (usesCustomCreativePromptTemplate(config)) return buildCustomCreativeVideoPrompt(config);
  return buildAiShowcaseVideoPrompt(config);
}

function publicProducts() {
  return getPlatformProducts().map((product) => ({
    id: product.id,
    name: product.name,
    shortName: product.shortName,
    spokenName: String(product.spokenName || product.shortName || product.name),
    spokenAliases: Array.isArray(product.spokenAliases)
      ? product.spokenAliases.map((alias) => ({
        id: String(alias.id || ""),
        label: String(alias.label || "其他简称"),
        value: String(alias.value || "")
      })).filter((alias) => alias.id && alias.value)
      : [],
    category: product.category || "",
    imageDir: product.imageDir,
    defaultScene: product.defaultScene,
    defaultPurpose: product.defaultPurpose,
    visualIdentity: String(product.visualIdentity || ""),
    benefitCues: String(product.benefitCues || ""),
    maskDetail: String(product.maskDetail || ""),
    compliance: String(product.compliance || ""),
    negativeExtra: String(product.negativeExtra || ""),
    controlPrompt: String(product.controlPrompt || ""),
    productProfile: product.productProfile || null,
    replacementContract: product.replacementContract || null,
    imagePriority: Array.isArray(product.imagePriority) ? product.imagePriority.map(String) : [],
    commerce: {
      unitSpec: String(product.commerce?.unitSpec || ""),
      offers: Array.isArray(product.commerce?.offers)
        ? product.commerce.offers.map((offer) => ({
          id: String(offer.id || ""),
          label: String(offer.label || ""),
          spoken: String(offer.spoken || "")
        })).filter((offer) => offer.id && offer.label)
        : []
    },
    source: product.source || "built-in",
    pluginId: product.pluginId || "",
    pluginVersion: product.pluginVersion || ""
  }));
}

function jsonResponse(res, status, data) {
  const body = JSON.stringify(data, null, 2);
  res.writeHead(status, {
    "Content-Type": "application/json; charset=utf-8",
    "Cache-Control": "no-store, no-cache, must-revalidate, proxy-revalidate",
    "Pragma": "no-cache",
    "Expires": "0",
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Headers": "Content-Type",
    "Access-Control-Allow-Methods": "GET,POST,OPTIONS",
    "Content-Length": Buffer.byteLength(body)
  });
  res.end(body);
}

function textResponse(res, status, text, type = "text/plain; charset=utf-8") {
  res.writeHead(status, {
    "Content-Type": type,
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Headers": "Content-Type",
    "Access-Control-Allow-Methods": "GET,POST,OPTIONS"
  });
  res.end(text);
}

async function readJson(req) {
  const chunks = [];
  for await (const chunk of req) chunks.push(chunk);
  const raw = Buffer.concat(chunks).toString("utf8");
  return raw ? JSON.parse(raw) : {};
}

async function readSmallJson(req, maxBytes = 32 * 1024) {
  const chunks = [];
  let bytes = 0;
  for await (const chunk of req) {
    bytes += chunk.length;
    if (bytes > maxBytes) throw new Error("提交内容过大");
    chunks.push(chunk);
  }
  const raw = Buffer.concat(chunks).toString("utf8");
  return raw ? JSON.parse(raw) : {};
}

function normalizedEmployeeId(value) {
  return String(value || "").trim().replace(/\s+/g, "").toUpperCase();
}

function employeeIdFromAuthUser(user = {}) {
  const explicit = [
    user.work_no,
    user.workNo,
    user.employee_id,
    user.employeeId,
    user.employee_no,
    user.employeeNo
  ].map(normalizedEmployeeId).find(Boolean);
  if (explicit) return explicit;
  const subject = normalizedEmployeeId(user.sub);
  return /^FD-?\d+$/.test(subject) ? subject : "";
}

async function validateProviderUacToken(token, authUser = {}) {
  const baseUrl = String(process.env.KOC_GPT_IMAGE_BASE_URL || "https://jenvideo-jump.fandow.com")
    .trim()
    .replace(/\/+$/, "");
  let response;
  try {
    response = await fetch(`${baseUrl}/v1/agent-token`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
        Accept: "application/json",
        "User-Agent": `FandaoAIWorkbench/${APP_VERSION}`,
        "Content-Length": "0"
      },
      signal: AbortSignal.timeout(30_000)
    });
  } catch {
    throw new Error("公司模型授权服务暂时不可用，请稍后重试");
  }
  const payload = await response.json().catch(() => ({}));
  const agentToken = String(payload?.data?.token || payload?.token || "").trim();
  if (!response.ok || !agentToken) {
    if ([401, 403].includes(response.status)) {
      throw new Error("FanDo API Key 已失效，请先在 FanDo 重新登录后再次导入");
    }
    throw new Error(String(payload?.error || payload?.message || `公司模型授权校验失败（HTTP ${response.status}）`));
  }
  const workNo = normalizedEmployeeId(
    payload?.data?.work_no
    || payload?.data?.workNo
    || payload?.work_no
    || payload?.workNo
  );
  const expectedWorkNo = employeeIdFromAuthUser(authUser);
  if (workNo && expectedWorkNo && workNo !== expectedWorkNo) {
    throw new Error("所选 FanDo 授权不属于当前飞书账号，请切换为本人 FanDo 登录后重试");
  }
  let probeResponse;
  try {
    probeResponse = await fetch(`${baseUrl}/v1/session`, {
      method: "GET",
      headers: {
        "X-Access-Token": agentToken,
        Accept: "application/json",
        "User-Agent": `FandaoAIWorkbench/${APP_VERSION}`
      },
      signal: AbortSignal.timeout(15_000)
    });
  } catch {
    throw new Error("API Key 已通过换签，但最小可用性探针暂时无法访问，请稍后重试");
  }
  const probePayload = await probeResponse.json().catch(() => ({}));
  const probeBusinessError = probePayload?.error
    || (typeof probePayload?.code === "number" && probePayload.code !== 0);
  if (!probeResponse.ok || probeBusinessError) {
    if ([401, 403].includes(probeResponse.status)) {
      throw new Error("API Key 可以换签，但生成服务会话探针未通过，请在 FanDo 重新登录后重试");
    }
    throw new Error(String(
      probePayload?.error
      || probePayload?.message
      || probePayload?.detail
      || `API Key 最小可用性探针失败（HTTP ${probeResponse.status}）`
    ));
  }
  const checkedAt = new Date().toISOString();
  return {
    workNo,
    validatedAt: checkedAt,
    probeKind: "jenvideo-session",
    probeAt: checkedAt
  };
}

function teamServiceLoginError(code, message) {
  const error = new Error(`${message}。请打开 ./login.html?connect=collaboration，使用与中枢相同的飞书账号连接协作目录。`);
  error.code = code;
  error.statusCode = 409;
  error.collaborationLoginRequired = true;
  error.collaborationLoginUrl = "./login.html?connect=collaboration";
  return error;
}

function teamServiceConnection(req, localAuth = authManager.authenticateRequest(req)) {
  if (req?.authInternal === true || localAuth?.internal === true) {
    throw teamServiceLoginError("COLLABORATION_PERSONAL_LOGIN_REQUIRED", "协作目录需要本人飞书登录");
  }
  if (!localAuth?.ok || !localAuth?.token) {
    throw teamServiceLoginError("COLLABORATION_LOGIN_REQUIRED", "中枢登录不能替代协作目录的本人登录凭证");
  }
  if (!req?.centralAccess || !["hub-session", "central-oa", "workbench-ticket"].includes(req.authSource)) {
    throw teamServiceLoginError("COLLABORATION_IDENTITY_UNCONFIRMED", "当前请求尚未完成中枢准入核验");
  }
  const ticketId = typeof localAuth.user?.lark_user_id === "string" ? localAuth.user.lark_user_id.trim() : "";
  if (!ticketId) {
    throw teamServiceLoginError("COLLABORATION_IDENTITY_UNCONFIRMED", "暂不能核验协作账号与当前中枢账号是否一致");
  }
  if (req.authSource === "hub-session" || req.authSource === "central-oa") {
    // OA admission has already succeeded. Bind its exact employee number using
    // separately read official contact evidence, never names or POST echoes.
    const identity = req.authUser?.collaborationIdentity;
    if (!identity || identity.idType !== "user_id" || identity.active !== true
      || !Number.isFinite(Date.parse(identity.validUntil)) || Date.parse(identity.validUntil) <= Date.now()
      || req.centralAccess.workbenchUser !== req.authUser
      || identity.employeeNumber !== req.authUser.number) {
      throw teamServiceLoginError("COLLABORATION_IDENTITY_UNCONFIRMED", "当前中枢账号尚无经官方通讯录核验的协作身份映射");
    }
    const claims = localAuth.user;
    // tenantId is aPaaS tenant_id; it is deliberately not Feishu tenant_key.
    // authenticateRequest has verified these original signed claims first.
    if (ticketId !== identity.userId || claims.iss !== identity.issuer
      || claims.aud !== identity.audience || claims.tenant_id !== identity.tenantId
      || typeof claims.sub !== "string" || !claims.sub.trim() || claims.sub.length > 128) {
      throw teamServiceLoginError("COLLABORATION_IDENTITY_MISMATCH", "协作账号或所属协作租户与当前中枢账号的核验记录不一致");
    }
    // aPaaS sub is the signed source subject for audit, not an OA employee ID.
    req.collaborationIdentityAudit = {employeeNumber:identity.employeeNumber,userId:ticketId,
      issuer:claims.iss,audience:claims.aud,tenantId:claims.tenant_id,subject:claims.sub,
      sourceReadAt:identity.sourceReadAt,sourceSha256:identity.sourceSha256};
  } else {
    // The original native-ticket path keeps the same verified ticket identity.
    const currentId = typeof req?.authUser?.lark_user_id === "string" ? req.authUser.lark_user_id.trim() : "";
    if (!currentId) throw teamServiceLoginError("COLLABORATION_IDENTITY_UNCONFIRMED", "暂不能核验协作账号与当前中枢账号是否一致");
    if (currentId !== ticketId) throw teamServiceLoginError("COLLABORATION_IDENTITY_MISMATCH", "协作账号与当前中枢账号不一致");
  }
  return { kind: "workbench-ticket", headers: { "X-Workbench-Ticket": localAuth.token } };
}

function teamServiceRoute(connection, pathname = "") {
  if (connection?.kind !== "workbench-ticket") throw new Error("协作请求尚未核验本人身份");
  const route = pathname.startsWith("/") ? pathname : `/${pathname}`;
  return route.replace(/^\/api\/team-workbench\b/, "/openapi/team-workbench");
}

function teamServiceUrl(connection, pathname = "") {
  const gatewayUrl = authManager.getConfig().gatewayUrl.replace(/\/+$/, "");
  if (!gatewayUrl) throw new Error("部门协作服务地址尚未配置");
  return new URL(`${gatewayUrl}${teamServiceRoute(connection, pathname)}`);
}

let integratedTeamCatalog = null;
async function teamServiceRequest(req, pathname, options = {}) {
  if (process.env.HUB_INTEGRATED_MODE === "1") {
    if (!integratedTeamCatalog) {
      integratedTeamCatalog = require("./hub-team-catalog.js").createHubTeamCatalog(process.env.WIS_TEAM_CATALOG_DB);
    }
    return integratedTeamCatalog.request(req, pathname, options);
  }
  const connection = teamServiceConnection(req);
  const userCredentialHeaders = connection.headers;
  const collaborationApiKey = String(authManager.getConfig().collaborationApiKey || "").trim();
  if (!collaborationApiKey) throw new Error("部门协作服务密钥尚未配置，请更新工作台");
  const target = teamServiceUrl(connection, pathname);
  const body = options.body === undefined ? "" : JSON.stringify(options.body);
  const csrfToken = crypto.randomBytes(18).toString("base64url");
  const requestCookie = [
    String(userCredentialHeaders.Cookie || "").trim(),
    body ? `suda-csrf-token=${csrfToken}` : ""
  ].filter(Boolean).join("; ");
  return new Promise((resolve, reject) => {
    const request = https.request(target, {
      method: options.method || "GET",
      headers: {
        Authorization: `Bearer ${collaborationApiKey}`,
        "X-Api-Key": collaborationApiKey,
        ...userCredentialHeaders,
        Accept: "application/json",
        ...(body ? {
          "Content-Type": "application/json; charset=utf-8",
          "Content-Length": Buffer.byteLength(body),
          "X-Suda-Csrf-Token": csrfToken
        } : {}),
        ...(requestCookie ? { Cookie: requestCookie } : {})
      },
      timeout: 30000
    }, (response) => {
      const chunks = [];
      let bytes = 0;
      response.on("data", (chunk) => {
        bytes += chunk.length;
        if (bytes <= 4 * 1024 * 1024) chunks.push(chunk);
      });
        response.on("end", () => {
          const contentType = String(response.headers["content-type"] || "").toLowerCase();
          let data = {};
          let parsedJson = false;
          try {
            data = JSON.parse(Buffer.concat(chunks).toString("utf8") || "{}");
            parsedJson = true;
          } catch {
            data = { error: "部门协作服务返回了无法识别的内容" };
          }
          if (Number(response.statusCode || 500) >= 300) {
            reject(new Error(teamServiceErrorMessage(
              data,
              `部门协作服务请求未完成（HTTP ${response.statusCode}）`
            )));
            return;
          }
          if (!teamServiceResponseIsValid(connection, data, contentType, parsedJson)) {
            reject(new Error(teamServiceErrorMessage(
              data,
              teamServiceInvalidResponseMessage(response, data, contentType)
            )));
            return;
          }
          resolve(data);
      });
    });
    request.on("timeout", () => request.destroy(new Error("部门协作服务连接超时")));
    request.on("error", reject);
    if (body) request.write(body);
    request.end();
  });
}

function teamServiceResponseIsValid(connection, data, contentType = "", parsedJson = true) {
  if (connection?.kind !== "workbench-ticket") return false;
  if (!parsedJson) return false;
  if (!data || typeof data !== "object" || Array.isArray(data)) return false;
  if (String(contentType).split(";", 1)[0].trim().toLowerCase() !== "application/json") return false;
  return data.ok === true && data.success !== false && !data.error;
}

function teamServiceInvalidResponseMessage(response, data, contentType = "") {
  const statusCode = Number(response?.statusCode || 0) || "未知";
  const mimeType = String(contentType || "未知").split(";", 1)[0].trim() || "未知";
  const keys = data && typeof data === "object" && !Array.isArray(data)
    ? Object.keys(data).sort().slice(0, 8).join(",")
    : "";
  return `部门协作服务未返回有效结果（HTTP ${statusCode}，类型 ${mimeType}，字段 ${keys || "无"}）`;
}

function teamServiceErrorMessage(data, fallback = "部门协作服务暂不可用") {
  const readable = (value, depth = 0) => {
    if (depth > 4 || value === null || value === undefined) return "";
    if (typeof value === "string") return value.trim();
    if (typeof value === "number" || typeof value === "boolean") return String(value);
    if (Array.isArray(value)) {
      return value.map((item) => readable(item, depth + 1)).filter(Boolean).join("；");
    }
    if (typeof value === "object") {
      for (const key of ["message", "detail", "error", "msg", "reason"]) {
        const text = readable(value[key], depth + 1);
        if (text) return text;
      }
    }
    return "";
  };
  return readable(data) || fallback;
}

function teamServiceUserCredentialHeaders(req, localAuth = authManager.authenticateRequest(req)) {
  return teamServiceConnection(req, localAuth).headers;
}

function teamServiceForwardedCookieHeader() {
  // Native collaboration uses its signed ticket; no OA or browser cookie is
  // sent to another login surface. The request's own CSRF cookie is unchanged.
  return "";
}

async function fetchAllTeamResources(req, type, maxItems = 5000) {
  const items = [];
  let page = 1;
  while (items.length < maxItems) {
    const result = await teamServiceRequest(
      req,
      `/api/team-workbench/resources?type=${encodeURIComponent(type)}&page=${page}&pageSize=100`
    );
    if (!Array.isArray(result.items)) {
      throw new Error("共享目录未返回可核验的列表，已保留本机缓存，请稍后重试读取。");
    }
    const rows = result.items;
    items.push(...rows);
    const total = Number(result.total || result.pagination?.total || 0);
    const pages = Number(result.pages || result.pagination?.pages || 0);
    if (!rows.length || (total > 0 && items.length >= total) || (pages > 0 && page >= pages) || rows.length < 100) break;
    page += 1;
  }
  return items.slice(0, maxItems);
}

function readCopyLibraryAssets() {
  try {
    const parsed = JSON.parse(fs.readFileSync(COPY_LIBRARY_ASSETS_PATH, "utf8"));
    return {
      version: String(parsed.version || ""),
      generatedAt: String(parsed.generatedAt || ""),
      firstCreation: Array.isArray(parsed.firstCreation) ? parsed.firstCreation : [],
      secondCreationOriginals: Array.isArray(parsed.secondCreationOriginals) ? parsed.secondCreationOriginals : [],
      summary: parsed.summary || {}
    };
  } catch (error) {
    throw new Error(`工作台完整文案库未正确安装：${error.message}`);
  }
}

function copyLibraryResources(corpus) {
  return [...corpus.firstCreation, ...corpus.secondCreationOriginals].map((item) => ({
    recordKey: `copy:${item.library}:${item.id}`,
    recordType: "copy_framework",
    title: String(item.title || "未命名文案"),
    productName: String(item.productName || ""),
    sourceType: String(item.sourceType || "copy_library"),
    sourceUrl: String(item.sourceUrl || ""),
    status: "active",
    approved: true,
    metadata: {
      library: String(item.library || ""),
      assetId: String(item.id || ""),
      tag: String(item.tag || ""),
      categoryId: String(item.categoryId || ""),
      category: String(item.category || ""),
      description: String(item.description || ""),
      evidenceTier: String(item.evidenceTier || ""),
      matchedVideo: String(item.matchedVideo || ""),
      riskNote: String(item.riskNote || ""),
      originalText: String(item.fullText || item.originalText || "").slice(0, 50000),
      corpusVersion: corpus.version
    }
  }));
}

async function ensureRemixEntrySharedAssets(entry) {
  if (!entry || typeof entry !== "object") throw new Error("待共享的切片任务不存在");
  if (!entry.sharedStorageUrl && entry.filePath && fs.existsSync(entry.filePath)) {
    const uploaded = await materialCenter.sharedStorage.uploadFile(entry.filePath, {
      category: "remix-sources",
      identity: `${entry.id}-${String(entry.sha256 || "").slice(0, 12)}`
    });
    entry.sharedStorageUrl = uploaded.url;
    entry.sharedStoragePath = uploaded.key;
    entry.storageBackend = "aliyun-oss-yxb";
  }
  const clips = Array.isArray(entry.clips) ? entry.clips : [];
  let cursor = 0;
  const worker = async () => {
    while (cursor < clips.length) {
      const clip = clips[cursor];
      cursor += 1;
      if (!clip.sharedStorageUrl) {
        if (!clip.filePath || !fs.existsSync(clip.filePath)) throw new Error(`切片文件不存在：${clip.id}`);
        const uploaded = await materialCenter.sharedStorage.uploadFile(clip.filePath, {
          category: `remix-clips-v${Number(clip.segmentationVersion || 0) || "current"}`,
          identity: clip.id
        });
        clip.sharedStorageUrl = uploaded.url;
        clip.sharedStoragePath = uploaded.key;
        clip.storageBackend = "aliyun-oss-yxb";
      }
      if (!clip.sharedThumbnailUrl && clip.thumbnailPath && fs.existsSync(clip.thumbnailPath)) {
        const thumbnail = await materialCenter.sharedStorage.uploadFile(clip.thumbnailPath, {
          category: "remix-thumbnails",
          identity: clip.id,
          mime: "image/jpeg"
        });
        clip.sharedThumbnailUrl = thumbnail.url;
        clip.sharedThumbnailPath = thumbnail.key;
      }
    }
  };
  await Promise.all(Array.from({ length: Math.min(4, Math.max(1, clips.length)) }, () => worker()));
  await remixEngine.save();
  return entry;
}

async function syncSharedRemixLibrary(req, selectedEntries = null) {
  const state = remixEngine.getStateForTests();
  const entries = Array.isArray(selectedEntries) ? selectedEntries : (state.items || []);
  const resources = [];
  for (const item of entries) {
    const sharedStorageUrl = String(item.sharedStorageUrl || "");
    resources.push({
      recordKey: `feishu-asset:${item.id}`,
      recordType: "source_asset",
      title: `${item.productName || "历史有效成片"} · TOP${item.rank || "-"}`,
      productName: item.productName || "",
      sourceType: "feishu",
      sourceUrl: item.sourceDocUrl || "",
      storageUrl: sharedStorageUrl,
      status: item.status === "ready" ? "active" : "pending",
      approved: Boolean(item.selectedForInitial && item.approvalRisk !== "high"),
      metadata: {
        localSourceId: item.id,
        sourceToken: item.token || "",
        sourceDocTitle: item.sourceDocTitle || "",
        sourceSection: item.sourceSection || "",
        rank: Number(item.rank || 0),
        approvalRisk: item.approvalRisk || "",
        effectiveLabel: item.effectiveLabel || "",
        excludedByDefault: item.approvalRisk === "high" || item.selectedForInitial === false,
        duration: Number(item.metadata?.duration || 0),
        width: Number(item.metadata?.width || 0),
        height: Number(item.metadata?.height || 0),
        sha256: item.sha256 || "",
        sharedStorageReady: Boolean(sharedStorageUrl),
        sharedStoragePath: item.sharedStoragePath || "",
        sharedStorageExpiresAt: item.sharedStorageExpiresAt || "",
        clipCount: (item.clips || []).length,
        approvedClipCount: (item.clips || []).filter((clip) => clip.approved === true).length
      }
    });
    for (const clip of item.clips || []) {
      resources.push({
        recordKey: `clip:${clip.id}`,
        recordType: "clip",
        title: `${item.productName || "历史有效成片"} · TOP${item.rank || "-"} · ${clip.stageLabel || "片段"}`,
        productName: item.productName || "",
        sourceType: "feishu_cut",
        sourceUrl: item.sourceDocUrl || "",
        storageUrl: String(clip.sharedStorageUrl || ""),
        parentKey: `feishu-asset:${item.id}`,
        status: "active",
        approved: Boolean(clip.approved),
        metadata: {
          sourceId: item.id,
          clipId: clip.id,
          sourceRank: Number(item.rank || 0),
          productId: item.productId || "",
          productName: item.productName || "",
          start: Number(clip.start || 0),
          end: Number(clip.end || 0),
          duration: Number(clip.duration || 0),
          stage: clip.stage || "",
          stageLabel: clip.stageLabel || "",
          visualType: clip.visualType || "",
          transcript: clip.transcript || "",
          visibleText: clip.visibleText || "",
          cutBasis: clip.cutBasis || "",
          labelSource: clip.labelSource || "",
          confidence: Number(clip.confidence || 0),
          hasAudio: clip.hasAudio !== false,
          hasSpeechCandidate: clip.hasSpeechCandidate !== false,
          segmentationVersion: Number(clip.segmentationVersion || 0),
          preserveWhole: Boolean(clip.preserveWhole),
          allowResplit: Boolean(clip.allowResplit),
          reviewRequired: clip.reviewRequired !== false,
          sharedStorageReady: Boolean(clip.sharedStorageUrl),
          sharedStoragePath: clip.sharedStoragePath || "",
          thumbnailUrl: clip.sharedThumbnailUrl || "",
          sourceStorageUrl: sharedStorageUrl
        }
      });
    }
  }
  let synced = 0;
  for (let index = 0; index < resources.length; index += 150) {
    const batch = resources.slice(index, index + 150);
    const result = await teamServiceRequest(req, "/api/team-workbench/resources/batch", {
      method: "POST",
      body: { items: batch }
    });
    synced += Number(result.count || 0);
  }
  return {
    ok: true,
    sources: entries.length,
    clips: resources.filter((item) => item.recordType === "clip").length,
    synced,
    storageReady: resources.filter((item) => item.recordType === "source_asset" && item.storageUrl).length
  };
}

function requestActor(req) {
  const user = req.authUser || {};
  return String(user.name || user.username || user.email || user.open_id || user.openId || "workbench-user").slice(0, 128);
}

function requireProductWorkflowImageMetadata(input = {}) {
  const normalized = {
    ...input,
    title: String(input.title || "").trim(),
    productId: String(input.productId || "").trim(),
    assetRole: String(input.assetRole || "").trim(),
    productState: String(input.productState || "").trim()
  };
  const missing = [
    ["title", "资产名称"],
    ["productId", "所属 SKU"],
    ["assetRole", "资产角色"],
    ["productState", "产品形态"]
  ].filter(([key]) => !normalized[key]).map(([, label]) => label);
  if (missing.length) throw new Error(`产品图片必须填写：${missing.join("、")}`);
  return normalized;
}

