async function syncProductWorkflowAsset(req, asset) {
  if (!asset.storageUrl) throw new Error("OSS写入未完成，暂时无法同步共享资产目录");
  await teamServiceRequest(req, "/api/team-workbench/resources/batch", {
    method: "POST",
    body: { items: [productWorkflowAssetResource(asset)] }
  });
  await productWorkflows.syncSharedAssets([{ ...asset, metadataSyncStatus: "shared" }]);
  return { ok: true, status: "shared" };
}

async function removeSharedProductWorkflowAsset(req, asset) {
  if (asset.metadataSyncStatus !== "shared") return { ok: true, status: "not_shared" };
  const resource = productWorkflowAssetResource(asset);
  await teamServiceRequest(req, "/api/team-workbench/resources/batch", {
    method: "POST",
    body: {
      items: [{
        ...resource,
        storageUrl: "",
        status: "inactive",
        approved: false,
        metadata: {
          ...resource.metadata,
          deletedAt: new Date().toISOString(),
          deletedBy: requestActor(req)
        }
      }]
    }
  });
  return { ok: true, status: "removed" };
}

async function registerProductWorkflowAsset(req, filePath, input = {}) {
  const assetType = input.assetType === "video" ? "video" : "image";
  const assetInput = assetType === "image" ? requireProductWorkflowImageMetadata(input) : input;
  try {
    await hydrateSharedProductWorkflowSkus(req);
  } catch {}
  const product = productWorkflows.listManagedProducts().find((item) => item.id === String(assetInput.productId || ""));
  if (!product) throw new Error("所属SKU不存在，请先在资产库新增并保存SKU");
  if (product.status !== "active") throw new Error("所属SKU已停用，请先启用后再上传资产");
  const canonicalAssetInput = { ...assetInput, productName: product.name, category: product.category || "" };
  const originalName = String(input.name || (assetType === "video" ? "product-broll.mp4" : "product-image.jpg"));
  const kind = assetType === "video" ? "product-broll-video" : "product-asset-image";
  const metadata = validateUploadMetadata(kind, originalName);
  if (metadata.error) throw new Error(metadata.error);
  const pattern = assetType === "video" ? /\.(mp4|mov)$/i : /\.(png|jpe?g)$/i;
  const destination = await requireUploadedFile(filePath, pattern, assetType === "video" ? "碎镜头" : "产品图");
  const stat = await fsp.stat(destination);
  if (stat.size > metadata.config.maxBytes) throw new Error(metadata.config.label);
  const videoInfo = assetType === "video" ? await probeKocReferenceVideo(destination) : { duration: 0 };
  const asset = await productWorkflows.registerAsset(destination, {
    assetType,
    title: canonicalAssetInput.title || originalName,
    productId: canonicalAssetInput.productId,
    productName: canonicalAssetInput.productName,
    category: canonicalAssetInput.category,
    assetRole: canonicalAssetInput.assetRole || (assetType === "video" ? "product_broll" : "white_background"),
    productState: canonicalAssetInput.productState,
    view: canonicalAssetInput.view,
    style: canonicalAssetInput.style,
    duration: videoInfo.duration,
    source: "user_upload",
    owner: requestActor(req)
  });
  if (asset.duplicate === true) {
    await fsp.unlink(destination).catch(() => {});
    return {
      asset,
      duplicateAsset: true,
      duplicateReason: asset.duplicateReason || "sku_asset_type_sha256",
      duplicateMatch: asset.duplicateMatch || null,
      metadataSync: {
        ok: true,
        status: "duplicate_skipped",
        message: `已存在完全相同的资产“${asset.duplicateMatch?.title || asset.title || originalName}”，未重复写入 OSS`
      }
    };
  }
  let metadataSync = { ok: false, status: "local_pending", message: "" };
  try {
    metadataSync = await syncProductWorkflowAsset(req, asset);
  } catch (error) {
    metadataSync.message = error.message;
  }
  return { asset: productWorkflows.getAsset(asset.id), metadataSync };
}

async function hydrateSharedProductWorkflowAssets(req) {
  const resources = await fetchAllTeamResources(req, "product_workflow_asset", 5000);
  const assets = resources.map(productWorkflowAssetFromResource).filter(Boolean);
  await productWorkflows.syncSharedAssets(assets, { pruneMissing: true });
  return assets.length;
}

let workspaceAssetMigrationInFlight = null;

async function ensureWorkspaceAssetsMigrated(req) {
  if (!workspaceAssetMigrationInFlight) {
    workspaceAssetMigrationInFlight = (async () => {
      const migration = await productWorkflows.migrateWorkspaceAssets({ concurrency: 3 });
      const warnings = [...(migration.failed || []).map((item) => `${item.title || item.id}：${item.error}`)];
      let synced = 0;
      const pendingAssets = productWorkflows.listAssets().filter((asset) => (
        asset.storageUrl
        && asset.source === "built-in"
        && asset.metadataSyncStatus !== "shared"
      ));
      for (const asset of pendingAssets) {
        try {
          await syncProductWorkflowAsset(req, asset);
          synced += 1;
        } catch (error) {
          warnings.push(`${asset.title || asset.id}：${error.message}`);
        }
      }
      return {
        migrated: migration.migrated?.length || 0,
        synced,
        failed: migration.failed?.length || 0,
        warnings
      };
    })().finally(() => {
      workspaceAssetMigrationInFlight = null;
    });
  }
  return workspaceAssetMigrationInFlight;
}

function isPathInside(root, target) {
  const relative = path.relative(path.resolve(root), path.resolve(target));
  return Boolean(relative) && !relative.startsWith("..") && !path.isAbsolute(relative);
}

function uploadSessionName(value) {
  const normalized = String(value || "").replace(/[^a-zA-Z0-9_-]/g, "").slice(0, 64);
  return normalized || `upload-${Date.now()}-${crypto.randomBytes(3).toString("hex")}`;
}

function uploadFileName(originalName) {
  const baseName = path.basename(String(originalName || "素材"));
  const ext = path.extname(baseName).toLowerCase();
  const stem = safeName(path.basename(baseName, ext), "素材");
  return `${Date.now()}-${crypto.randomBytes(3).toString("hex")}-${stem}${ext}`;
}

function uploadKindConfig(kind) {
  return {
    "product-asset-image": { pattern: /\.(png|jpe?g)$/i, maxBytes: MAX_PRODUCT_ASSET_IMAGE_BYTES, label: "图片资产仅支持PNG或JPG，且不能超过10MB" },
    "product-scene-reference": { pattern: /\.(png|jpe?g)$/i, maxBytes: MAX_PRODUCT_ASSET_IMAGE_BYTES, label: "场景参考图仅支持PNG或JPG，且不能超过10MB" },
    "product-broll-video": { pattern: /\.(mp4|mov)$/i, maxBytes: MAX_REPLACEMENT_VIDEO_BYTES, label: "碎镜头仅支持MP4或MOV，且不能超过500MB" },
    "replacement-reference": { pattern: /\.(mp4|mov)$/i, maxBytes: MAX_ONE_CLICK_REPLACEMENT_VIDEO_BYTES, label: "一键换品参考视频仅支持MP4或MOV，且不能超过200MB" },
    "replacement-product": { pattern: /\.(png|jpe?g)$/i, maxBytes: MAX_PRODUCT_ASSET_IMAGE_BYTES, label: "临时产品图仅支持PNG或JPG，且不能超过10MB" },
    "replacement-first-frame": { pattern: /\.(png|jpe?g)$/i, maxBytes: MAX_PRODUCT_ASSET_IMAGE_BYTES, label: "自定义新首帧仅支持PNG或JPG，且不能超过10MB" },
    scene: { pattern: IMAGE_FILE_PATTERN, maxBytes: MAX_SCENE_UPLOAD_BYTES, label: "图片仅支持 png、jpg、jpeg、webp" },
    video: { pattern: VIDEO_FILE_PATTERN, maxBytes: MAX_VIDEO_UPLOAD_BYTES, label: "视频仅支持 mp4、mov、m4v、webm" },
    "koc-reference": { pattern: VIDEO_FILE_PATTERN, maxBytes: MAX_VIDEO_UPLOAD_BYTES, label: "原片仅支持 mp4、mov、m4v、webm" },
    "koc-character": { pattern: IMAGE_FILE_PATTERN, maxBytes: MAX_SCENE_UPLOAD_BYTES, label: "人物场景图仅支持 png、jpg、jpeg、webp" },
    "koc-product": { pattern: IMAGE_FILE_PATTERN, maxBytes: MAX_SCENE_UPLOAD_BYTES, label: "产品图仅支持 png、jpg、jpeg、webp" },
    "koc-audio": { pattern: AUDIO_FILE_PATTERN, maxBytes: MAX_AUDIO_UPLOAD_BYTES, label: "参考音频仅支持 mp3、m4a、aac、wav" },
    "variation-reference": { pattern: VIDEO_FILE_PATTERN, maxBytes: MAX_VIDEO_UPLOAD_BYTES, label: "母版视频仅支持 mp4、mov、m4v、webm" },
    "prompt-reverse-video": { pattern: VIDEO_FILE_PATTERN, maxBytes: MAX_VIDEO_UPLOAD_BYTES, label: "提示词逆推视频仅支持 mp4、mov、m4v、webm" },
    "variation-product": { pattern: IMAGE_FILE_PATTERN, maxBytes: MAX_SCENE_UPLOAD_BYTES, label: "目标产品图仅支持 png、jpg、jpeg、webp" },
    "variation-character": { pattern: IMAGE_FILE_PATTERN, maxBytes: MAX_SCENE_UPLOAD_BYTES, label: "人物参考图仅支持 png、jpg、jpeg、webp" },
    "variation-background": { pattern: IMAGE_FILE_PATTERN, maxBytes: MAX_SCENE_UPLOAD_BYTES, label: "背景参考图仅支持 png、jpg、jpeg、webp" },
    "remake-background": { pattern: IMAGE_FILE_PATTERN, maxBytes: MAX_PRODUCT_ASSET_IMAGE_BYTES, label: "做同款背景参考图仅支持 png、jpg、jpeg、webp，且不能超过10MB" },
    "remake-person": { pattern: IMAGE_FILE_PATTERN, maxBytes: MAX_PRODUCT_ASSET_IMAGE_BYTES, label: "做同款人物参考图仅支持 png、jpg、jpeg、webp，且不能超过10MB" },
    "remake-custom-candidate": { pattern: IMAGE_FILE_PATTERN, maxBytes: MAX_PRODUCT_ASSET_IMAGE_BYTES, label: "做同款自定义候选图仅支持 png、jpg、jpeg、webp，且不能超过10MB" }
  }[kind] || null;
}

function validateUploadMetadata(kind, originalName) {
  const config = uploadKindConfig(kind);
  if (!config) return { error: "不支持的上传类型" };
  if (!config.pattern.test(originalName)) return { error: config.label };
  return { config };
}

async function assembleUploadChunks(chunkDir, destination, totalChunks, expectedBytes) {
  let bytes = 0;
  const parts = [];
  for (let index = 0; index < totalChunks; index += 1) {
    const partPath = path.join(chunkDir, `${index}.part`);
    let stat;
    try {
      stat = await fsp.stat(partPath);
    } catch {
      throw new Error(`上传分片缺失：${index + 1}/${totalChunks}`);
    }
    if (!stat.isFile() || stat.size > PROXY_SAFE_UPLOAD_CHUNK_BYTES) {
      throw new Error(`上传分片无效：${index + 1}/${totalChunks}`);
    }
    bytes += stat.size;
    parts.push(partPath);
  }
  if (bytes !== expectedBytes) throw new Error(`上传文件大小校验失败：应为 ${expectedBytes}B，实际 ${bytes}B`);

  await fsp.mkdir(path.dirname(destination), { recursive: true });
  const output = fs.createWriteStream(destination, { flags: "wx" });
  try {
    for (const partPath of parts) {
      await pipeline(fs.createReadStream(partPath), output, { end: false });
    }
    await new Promise((resolve, reject) => {
      output.once("finish", resolve);
      output.once("error", reject);
      output.end();
    });
  } catch (error) {
    output.destroy();
    await fsp.rm(destination, { force: true }).catch(() => {});
    throw error;
  }
  await fsp.rm(chunkDir, { recursive: true, force: true });
  return bytes;
}

async function saveUploadRequest(req, destination, maxBytes) {
  await fsp.mkdir(path.dirname(destination), { recursive: true });
  let bytes = 0;
  const limiter = new Transform({
    transform(chunk, encoding, callback) {
      bytes += chunk.length;
      if (bytes > maxBytes) {
        callback(new Error(`文件超过上传上限 ${formatBytes(maxBytes)}`));
        return;
      }
      callback(null, chunk);
    }
  });
  try {
    await pipeline(req, limiter, fs.createWriteStream(destination));
  } catch (error) {
    await fsp.rm(destination, { force: true }).catch(() => {});
    throw error;
  }
  return bytes;
}

function parseSpaceId(libtvUrl) {
  const text = String(libtvUrl || "").trim();
  if (/^\d+$/.test(text)) return text;
  const url = new URL(text);
  const spaceId = url.searchParams.get("spaceId");
  if (!spaceId) throw new Error("LibTV 链接里没有 spaceId");
  return spaceId;
}

function runLibtv(args, options = {}) {
  assertLibtvArgsPromptRulesDisabled(args, { workflow: options.workflow || "LibTV 视频任务" });
  return new Promise((resolve) => {
    const scope = options.libtvScope || currentLibtvUserScope();
    const env = libtvChildEnvironment(scope);
    if (!scope || !env) {
      resolve({ code: 1, stdout: "", stderr: "当前工作台账号尚未建立LibTV凭证空间" });
      return;
    }
    const nodeScript = String(process.env.LIBTV_NODE_SCRIPT || "").trim();
    const child = spawn(nodeScript ? process.execPath : LIBTV, nodeScript ? [nodeScript, ...args] : args, {
      cwd: options.cwd || APP_ROOT,
      windowsHide: true,
      env
    });
    let stdout = "";
    let stderr = "";
    child.stdout.on("data", (chunk) => {
      stdout += chunk.toString("utf8");
      if (options.onStdout) options.onStdout(chunk.toString("utf8"));
    });
    child.stderr.on("data", (chunk) => {
      stderr += chunk.toString("utf8");
      if (options.onStderr) options.onStderr(chunk.toString("utf8"));
    });
    child.on("error", (error) => {
      resolve({ code: 1, stdout, stderr: stderr + "\n" + error.message });
    });
    child.on("close", (code) => resolve({ code, stdout, stderr }));
  });
}

function waitMs(milliseconds) {
  return new Promise((resolve) => setTimeout(resolve, milliseconds));
}

function clearLibtvModelAvailabilityCache(scope = currentLibtvUserScope()) {
  const scopeKey = String(scope?.key || "").trim();
  if (!scopeKey) return;
  for (const key of libtvModelAvailabilityCache.keys()) {
    if (key.startsWith(`${scopeKey}:`)) libtvModelAvailabilityCache.delete(key);
  }
}

function readLibtvCredentials(scope = currentLibtvUserScope()) {
  if (!scope?.configDir) throw new Error("当前工作台账号尚未登录 LibTV");
  const credentialsPath = path.join(scope.configDir, "credentials.json");
  let credentials;
  try {
    credentials = JSON.parse(fs.readFileSync(credentialsPath, "utf8"));
  } catch {
    throw new Error("当前工作台账号尚未登录 LibTV");
  }
  const token = String(credentials?.usertoken || "").trim();
  if (!token) throw new Error("当前工作台账号的 LibTV 登录凭证已失效");
  return {
    token,
    webid: String(credentials?.webid || "").trim()
  };
}

async function requestLibtvAccountJson(baseUrl, pathname, options = {}) {
  const credentials = readLibtvCredentials(options.scope);
  const method = options.method || "GET";
  const response = await fetch(`${baseUrl}${pathname}`, {
    method,
    headers: {
      token: credentials.token,
      webid: credentials.webid,
      "x-language": "zh",
      "X-from-client": "cli",
      "X-Log-ID": crypto.randomUUID(),
      Accept: "application/json",
      ...(method === "POST" ? { "Content-Type": "application/json" } : {})
    },
    ...(method === "POST" ? { body: JSON.stringify(options.body || {}) } : {}),
    signal: AbortSignal.timeout(Number(options.timeoutMs || 8_000))
  });
  let payload;
  try {
    payload = await response.json();
  } catch {
    throw new Error(`LibTV 积分接口返回了无法识别的内容（${response.status}）`);
  }
  if (!response.ok || Number(payload?.code) !== 0) {
    throw new Error(String(payload?.msg || `LibTV 积分接口请求失败（${response.status}）`));
  }
  return payload;
}

function normalizedThirdAssetCheckList(value) {
  if (Array.isArray(value)) return value;
  if (Array.isArray(value?.list)) return value.list;
  if (Array.isArray(value?.data?.list)) return value.data.list;
  return [];
}

async function reviewLibtvThirdAssets(items, options = {}) {
  const assets = (Array.isArray(items) ? items : []).map((item, index) => ({
    ...item,
    itemId: String(item?.itemId || item?.nodeKey || item?.nodeName || `asset-${index + 1}`),
    assetType: String(item?.assetType || "").trim(),
    url: String(item?.url || "").trim()
  }));
  if (!assets.length) return { allPassed: true, results: [] };

  const request = typeof options.request === "function"
    ? options.request
    : async (pathname, body) => {
        const payload = await requestLibtvAccountJson(LIBTV_VIDEO_API_BASE_URL, pathname, {
          method: "POST",
          body,
          timeoutMs: 15_000
        });
        return payload?.data;
      };
  const wait = typeof options.wait === "function" ? options.wait : waitMs;
  const pollIntervalMs = Number.isFinite(Number(options.pollIntervalMs))
    ? Math.max(0, Number(options.pollIntervalMs))
    : REPLACEMENT_COMPLIANCE_POLL_INTERVAL_MS;
  const maxAttempts = Number.isFinite(Number(options.maxAttempts))
    ? Math.max(1, Number(options.maxAttempts))
    : REPLACEMENT_COMPLIANCE_MAX_ATTEMPTS;
  const onProgress = typeof options.onProgress === "function" ? options.onProgress : async () => {};
  const results = new Map();
  const pendingByUuid = new Map();

  await Promise.all(assets.map(async (asset) => {
    if (!asset.assetType || !asset.url) {
      results.set(asset.itemId, { ...asset, status: "unavailable", detail: "素材节点缺少可检测的远程地址" });
      return;
    }
    try {
      const created = await request(LIBTV_THIRD_ASSET_CREATE_PATH, {
        assetUrl: asset.url,
        assetType: asset.assetType,
        version: 1
      });
      const uuid = String(created?.uuid || "").trim();
      if (!uuid) {
        results.set(asset.itemId, { ...asset, status: "unavailable", detail: "LibTV 未返回单项审核编号" });
        return;
      }
      pendingByUuid.set(uuid, asset);
      results.set(asset.itemId, { ...asset, uuid, status: "pending" });
    } catch (error) {
      results.set(asset.itemId, { ...asset, status: "unavailable", detail: error.message });
    }
  }));

  let attempt = 0;
  while (pendingByUuid.size && attempt < maxAttempts) {
    attempt += 1;
    await wait(pollIntervalMs);
    let checks;
    try {
      checks = normalizedThirdAssetCheckList(await request(LIBTV_THIRD_ASSET_CHECK_PATH, {
        uuids: [...pendingByUuid.keys()]
      }));
    } catch (error) {
      for (const [uuid, asset] of pendingByUuid) {
        results.set(asset.itemId, { ...asset, uuid, status: "unavailable", detail: error.message });
      }
      pendingByUuid.clear();
      break;
    }
    for (const checked of checks) {
      const uuid = String(checked?.uuid || "").trim();
      const asset = pendingByUuid.get(uuid);
      if (!asset || checked?.found === false) continue;
      const status = Number(checked?.status);
      if (status === 1) {
        const assetId = String(checked?.assetId || "").trim();
        const imageExempt = !assetId && asset.assetType === "image";
        const passed = Boolean(assetId || imageExempt);
        results.set(asset.itemId, {
          ...asset,
          uuid,
          status: passed ? "passed" : "rejected",
          assetId,
          detail: passed ? "" : "审核完成，但未生成该视频或音频的合规资产 ID"
        });
        pendingByUuid.delete(uuid);
      } else if (status === 2) {
        results.set(asset.itemId, { ...asset, uuid, status: "rejected", detail: "未通过 LibTV 合规审核" });
        pendingByUuid.delete(uuid);
      }
    }
    await onProgress({ attempt, pending: pendingByUuid.size, total: assets.length });
  }

  for (const [uuid, asset] of pendingByUuid) {
    results.set(asset.itemId, { ...asset, uuid, status: "unavailable", detail: "单项审核结果查询超时" });
  }
  const ordered = assets.map((asset) => results.get(asset.itemId));
  return {
    allPassed: ordered.every((result) => result?.status === "passed"),
    results: ordered
  };
}

function libtvResourceNodeUrl(payload) {
  const raw = payload?.data?.url ?? payload?.url;
  const candidates = Array.isArray(raw) ? raw : [raw];
  for (const candidate of candidates) {
    const value = typeof candidate === "string" ? candidate : candidate?.url;
    if (/^https?:\/\//i.test(String(value || "").trim())) return String(value).trim();
  }
  return "";
}

function oneClickReplacementComplianceAssets(job = {}) {
  const assets = [];
  const seen = new Set();
  const add = (assetType, label, asset) => {
    const nodeReference = remoteNodeRef(asset);
    if (!nodeReference) return;
    const itemId = `${assetType}:${nodeReference}`;
    if (seen.has(itemId)) return;
    seen.add(itemId);
    const fileName = path.basename(String(asset?.path || "").trim()) || String(asset?.nodeName || nodeReference).trim();
    assets.push({
      itemId,
      assetType,
      label,
      fileName,
      nodeReference,
      nodeKey: String(asset?.nodeKey || "").trim(),
      nodeName: String(asset?.nodeName || "").trim()
    });
  };
  for (const asset of job.sourceVideoUploads || []) add("video", "参考视频", asset);
  const sceneUploads = Array.isArray(job.sceneUploads) && job.sceneUploads.length ? job.sceneUploads : (job.sceneUpload ? [job.sceneUpload] : []);
  for (let index = 0; index < sceneUploads.length; index += 1) add("image", index ? `分镜${index + 1}关键帧` : "选定的新首帧", sceneUploads[index]);
  for (let index = 0; index < (job.productAssetUploads || []).length; index += 1) {
    add("image", `目标产品图${index + 1}`, job.productAssetUploads[index]);
  }
  if (oneClickReplacementUsesAudioUpstream(job.config || {})) {
    for (const asset of job.referenceAudioUploads || []) {
      const clipIndex = Number(asset?.clipIndex || 0);
      add("audio", clipIndex ? `第${clipIndex}段参考音频` : "参考音频", asset);
    }
  }
  return assets;
}

async function performOneClickReplacementComplianceDiagnosis(job, options = {}) {
  const run = typeof options.run === "function" ? options.run : runLibtv;
  const review = typeof options.review === "function" ? options.review : reviewLibtvThirdAssets;
  const assets = oneClickReplacementComplianceAssets(job);
  const readable = [];
  const unavailable = [];
  await Promise.all(assets.map(async (asset) => {
    try {
      const result = await run(["node", asset.nodeReference, "-p", job.projectId]);
      if (result?.code !== 0) throw new Error(String(result?.stderr || result?.stdout || "读取素材节点失败").trim());
      const payload = tryParseJson(result?.stdout) || {};
      const url = libtvResourceNodeUrl(payload);
      if (!url) throw new Error("素材节点尚未返回可检测的远程地址");
      readable.push({ ...asset, url });
    } catch (error) {
      unavailable.push({ ...asset, status: "unavailable", detail: error.message });
    }
  }));
  const reviewed = readable.length ? await review(readable, options.reviewOptions || {}) : { results: [] };
  const byId = new Map([...(reviewed.results || []), ...unavailable].map((item) => [item.itemId, item]));
  return { results: assets.map((asset) => byId.get(asset.itemId) || { ...asset, status: "unavailable", detail: "未取得单项结果" }) };
}

async function diagnoseOneClickReplacementComplianceFailure(job, options = {}) {
  if (options.run || options.review || !job?.id) return performOneClickReplacementComplianceDiagnosis(job, options);
  let flight = oneClickReplacementComplianceDiagnosisFlights.get(job.id);
  if (!flight) {
    flight = performOneClickReplacementComplianceDiagnosis(job, options);
    oneClickReplacementComplianceDiagnosisFlights.set(job.id, flight);
    const timer = setTimeout(() => oneClickReplacementComplianceDiagnosisFlights.delete(job.id), 5 * 60_000);
    if (typeof timer.unref === "function") timer.unref();
  }
  return flight;
}

function nonNegativePower(value) {
  const numeric = Number(value);
  return Number.isFinite(numeric) && numeric > 0 ? numeric : 0;
}

function libtvAccountData(payload = {}) {
  return payload?.data && typeof payload.data === "object" ? payload.data : payload;
}

function libtvGeneralUsablePower(payload = {}) {
  const attr = libtvAccountData(payload)?.attr || {};
  const usablePower = Number(attr.usablePower);
  if (Number.isFinite(usablePower) && usablePower >= 0) return usablePower;
  return nonNegativePower(attr.rechargeUsablePower)
    + nonNegativePower(attr.freeUsablePower)
    + nonNegativePower(attr.libtvUsablePower);
}

function libtvDedicatedUsablePower(payload = {}, modelKeys = []) {
  const accepted = new Set((Array.isArray(modelKeys) ? modelKeys : [modelKeys])
    .map((value) => String(value || "").trim())
    .filter(Boolean));
  if (!accepted.size) return 0;
  const account = libtvAccountData(payload);
  const entries = Array.isArray(account?.attr?.exPowerSummary?.list)
    ? account.attr.exPowerSummary.list
    : [];
  return entries.reduce((sum, entry) => {
    const models = Array.isArray(entry?.models) ? entry.models : [];
    const matches = models.some((model) => {
      const keys = Array.isArray(model?.modelKey) ? model.modelKey : [model?.modelKey];
      return keys.some((key) => accepted.has(String(key || "").trim()));
    });
    return sum + (matches ? nonNegativePower(entry?.usablePower) : 0);
  }, 0);
}

function aiShowcaseVideoModelsWithAvailability(accountPayload, requiredPowerByModelId = {}) {
  const accountKnown = Boolean(accountPayload && typeof accountPayload === "object");
  const generalPower = accountKnown ? libtvGeneralUsablePower(accountPayload) : 0;
  return AI_SHOWCASE_VIDEO_MODELS.map((model) => {
    const billing = AI_SHOWCASE_VIDEO_MODEL_BILLING[model.id];
    const requiredPower = Number(requiredPowerByModelId?.[model.id]);
    if (!accountKnown || !billing || !Number.isFinite(requiredPower) || requiredPower < 0) {
      return {
        ...model,
        availability: "unknown",
        availabilityMessage: "LibTV 模型积分暂未检测，提交任务时会再次校验"
      };
    }
    const dedicatedPower = libtvDedicatedUsablePower(accountPayload, [billing.modelKey, billing.checkpointId]);
    const usablePower = generalPower + dedicatedPower;
    const available = usablePower >= requiredPower;
    return {
      ...model,
      available,
      availability: available ? "available" : "insufficient",
      requiredPower,
      usablePower,
      generalUsablePower: generalPower,
      dedicatedUsablePower: dedicatedPower,
      availabilityMessage: available
        ? `可用积分 ${usablePower}，本次预计消耗 ${requiredPower}`
        : `积分不足（本次预计需要 ${requiredPower}，当前可用 ${usablePower}）`,
      ...(available ? {} : { unavailableReason: `积分不足：需 ${requiredPower}，可用 ${usablePower}` })
    };
  });
}

function defaultAvailableAiShowcaseVideoModelId(videoModels = AI_SHOWCASE_VIDEO_MODELS) {
  return videoModels.find((model) => model.available === true)?.id
    || videoModels.find((model) => model.available !== false)?.id
    || videoModels[0]?.id
    || "";
}

function libtvPowerCalculatorBody(videoModel, duration, accountPayload = {}, options = {}) {
  const billing = AI_SHOWCASE_VIDEO_MODEL_BILLING[videoModel.id];
  if (!billing) throw new Error(`${videoModel.label} 尚未配置 LibTV 积分估算参数`);
  const teamId = Number(libtvAccountData(accountPayload)?.teamId || 0);
  const normalizedDuration = normalizeAiShowcaseVideoDuration(videoModel, duration);
  const clarity = resolveAiShowcaseVideoClarity(videoModel, options.clarity);
  const videoGenerationMode = resolveAiShowcaseVideoGenerationMode(
    videoModel,
    options.videoGenerationMode,
    { fallbackToDefault: true }
  );
  const usesAutomaticGeometry = aiShowcaseVideoModeUsesAutomaticGeometry(videoModel, videoGenerationMode);
  return {
    params: {
      model: billing.modelKey,
      prompt: "模型积分可用性检测",
      textList: [],
      imageList: [],
      videoList: [],
      audioList: [],
      ...billing.params,
      modeType: videoGenerationMode.value,
      ratio: usesAutomaticGeometry ? "adaptive" : billing.params.ratio,
      duration: usesAutomaticGeometry ? 0 : normalizedDuration,
      ...(clarity && videoModel.claritySetting ? { [videoModel.claritySetting]: clarity.value } : {})
    },
    metadata: { node_id: "workbench-model-quota", project_id: "workbench-model-quota" },
    provider: billing.provider,
    model: billing.modelKey,
    taskType: "video",
    requestId: crypto.randomUUID(),
    ...(teamId > 0 ? { teamId } : {})
  };
}

async function readAiShowcaseVideoModelAvailability(options = {}) {
  const scope = options.scope || currentLibtvUserScope();
  const requestedDuration = Number(options.duration);
  const duration = Number.isFinite(requestedDuration) ? Math.max(1, Math.min(30, Math.round(requestedDuration))) : PRODUCT_VIDEO_MIN_DURATION;
  const clarity = String(options.clarity || "").trim().toLowerCase();
  const videoGenerationMode = String(options.videoGenerationMode || "").trim();
  const cacheKey = `${String(scope?.key || "anonymous")}:${duration}:${clarity || "default"}:${videoGenerationMode || "default"}`;
  const cached = libtvModelAvailabilityCache.get(cacheKey);
  if (!options.force && cached && Date.now() - cached.cachedAt < LIBTV_MODEL_AVAILABILITY_CACHE_MS) {
    return cached.value;
  }
  try {
    const accountPayload = await requestLibtvAccountJson(
      LIBTV_ACCOUNT_API_BASE_URL,
      LIBTV_MEMBER_ACCOUNT_PATH,
      { scope }
    );
    const powerEntries = await Promise.all(AI_SHOWCASE_VIDEO_MODELS.map(async (videoModel) => {
      try {
        const payload = await requestLibtvAccountJson(
          LIBTV_VIDEO_API_BASE_URL,
          LIBTV_POWER_CALCULATOR_PATH,
          {
            scope,
            method: "POST",
            body: libtvPowerCalculatorBody(videoModel, duration, accountPayload, { clarity, videoGenerationMode })
          }
        );
        const power = Number(payload?.data?.power);
        return [videoModel.id, Number.isFinite(power) && power >= 0 ? power : null];
      } catch {
        return [videoModel.id, null];
      }
    }));
    const requiredPowerByModelId = Object.fromEntries(powerEntries.filter(([, power]) => power !== null));
    const videoModels = aiShowcaseVideoModelsWithAvailability(accountPayload, requiredPowerByModelId);
    const value = {
      status: videoModels.some((model) => model.availability !== "unknown") ? "ready" : "unknown",
      duration,
      checkedAt: new Date().toISOString(),
      defaultVideoModelId: defaultAvailableAiShowcaseVideoModelId(videoModels),
      videoModels
    };
    libtvModelAvailabilityCache.set(cacheKey, { cachedAt: Date.now(), value });
    return value;
  } catch (error) {
    const videoModels = aiShowcaseVideoModelsWithAvailability(null, {});
    return {
      status: "unknown",
      duration,
      checkedAt: new Date().toISOString(),
      message: error.message,
      defaultVideoModelId: defaultAvailableAiShowcaseVideoModelId(videoModels),
      videoModels
    };
  }
}

function assertAiShowcaseVideoModelAvailable(videoModel, availability) {
  const checked = availability?.videoModels?.find((model) => model.id === videoModel.id);
  if (!checked || checked.available !== false) return checked || videoModel;
  const error = new Error(`${videoModel.label} 当前不可用：${checked.unavailableReason || "当前账号没有足够的可用积分"}。请选择有积分的模型。`);
  error.statusCode = 409;
  error.code = "LIBTV_MODEL_POINTS_INSUFFICIENT";
  throw error;
}

function normalizeLibtvAccounts(payload) {
  const source = Array.isArray(payload)
    ? payload
    : Array.isArray(payload?.accounts)
      ? payload.accounts
      : Array.isArray(payload?.data?.accounts)
        ? payload.data.accounts
        : [];
  return source.map((item) => {
    const accountId = String(item?.accountId || "").trim();
    if (!accountId) return null;
    const accountType = Number(item?.accountType || 0);
    return {
      accountId,
      accountName: String(item?.accountName || `LibTV账号 ${accountId}`).trim(),
      accountType,
      ownerType: Number(item?.ownerType || 0),
      isTeam: accountType === 2,
      isActive: item?.isActive === true
    };
  }).filter(Boolean);
}

function libtvAccountDisplay(account = {}, teamId = 0) {
  const name = String(account.accountName || "LibTV账号").trim();
  const isTeam = account.isTeam === true || Number(account.accountType || 0) === 2 || Number(teamId || 0) > 0;
  return `${name}（${isTeam ? "团队版" : "个人版"}${Number(teamId || 0) > 0 ? ` · ${Number(teamId)}` : ""}）`;
}

async function readLibtvAccountOptions() {
  const result = await runLibtv(["account", "list"]);
  if (result.code !== 0) {
    throw new Error(explainLibtvFailure(result, "读取LibTV个人/团队账号列表失败"));
  }
  return normalizeLibtvAccounts(tryParseJson(result.stdout));
}

async function readLibtvLoginStatus(options = {}) {
  const scope = currentLibtvUserScope();
  const libtvLoginState = libtvLoginStateFor(scope);
  if (!scope || !libtvLoginState) {
    return { ok: false, status: "idle", account: null, message: "请先使用个人工作台账号登录" };
  }
  const account = await runLibtv(["account", "info"]);
  if (account.code === 0) {
    const accountInfo = tryParseJson(account.stdout) || {};
    const activeScope = libtvActiveAccountScope(accountInfo);
    let accounts = [];
    let accountsWarning = "";
    if (options.includeAccounts) {
      try {
        accounts = await readLibtvAccountOptions();
      } catch (error) {
        accountsWarning = error.message;
      }
    }
    if (!accounts.length && activeScope.accountId) {
      accounts = [{
        accountId: activeScope.accountId,
        accountName: activeScope.accountName || `LibTV账号 ${activeScope.accountId}`,
        accountType: activeScope.accountType,
        ownerType: Number(accountInfo?.activeAccount?.ownerType || 0),
        isTeam: activeScope.accountType === 2 || activeScope.teamId > 0,
        isActive: true
      }];
    }
    accounts = accounts.map((item) => ({
      ...item,
      isActive: activeScope.accountId
        ? item.accountId === activeScope.accountId
        : item.isActive
    }));
    const activeAccount = accounts.find((item) => item.isActive) || accounts[0] || null;
    libtvLoginState.status = "connected";
    libtvLoginState.finishedAt = new Date().toISOString();
    libtvLoginState.message = "LibTV 已登录";
    return {
      ok: true,
      status: "connected",
      account: accountInfo,
      activeAccount: activeAccount ? {
        ...activeAccount,
        teamId: activeScope.teamId,
        displayName: libtvAccountDisplay(activeAccount, activeScope.teamId)
      } : null,
      accounts,
      accountsWarning,
      message: libtvLoginState.message
    };
  }
  if (libtvLoginState.status === "connected") {
    libtvLoginState.status = "idle";
    libtvLoginState.message = "";
  }
  return {
    ok: false,
    status: libtvLoginState.status,
    account: null,
    message: libtvLoginState.message || explainLibtvFailure(account, "LibTV 未登录")
  };
}

async function switchLibtvAccount(accountId) {
  const normalizedId = String(accountId || "").trim();
  if (!/^\d+$/.test(normalizedId)) throw new Error("请选择有效的LibTV个人或团队账号");
  const accounts = await readLibtvAccountOptions();
  const target = accounts.find((item) => item.accountId === normalizedId);
  if (!target) throw new Error("所选LibTV账号已不可用，请刷新后重新选择");
  const switched = await runLibtv(["account", "use", normalizedId]);
  if (switched.code !== 0) {
    throw new Error(explainLibtvFailure(switched, `切换到${target.accountName}失败`));
  }
  clearLibtvModelAvailabilityCache();
  const status = await readLibtvLoginStatus({ includeAccounts: true });
  if (!status.ok || status.activeAccount?.accountId !== normalizedId) {
    throw new Error("LibTV返回的当前生成空间与所选账号不一致，请重新选择");
  }
  return {
    ...status,
    message: `已切换到${status.activeAccount.displayName}`
  };
}

async function preferSingleLibtvTeamAccount() {
  const status = await readLibtvLoginStatus({ includeAccounts: true });
  if (!status.ok) return status;
  const teams = status.accounts.filter((item) => item.isTeam);
  if (teams.length === 1 && status.activeAccount?.accountId !== teams[0].accountId) {
    return switchLibtvAccount(teams[0].accountId);
  }
  return {
    ...status,
    requiresAccountSelection: teams.length > 1 && !status.activeAccount?.isTeam
  };
}

async function beginLibtvWebLogin() {
  return {
    ok: false,
    status: "phone_required",
    message: "请使用当前工作台账号本人的手机号和短信验证码登录 LibTV"
  };
}

function runProcess(binary, args, options = {}) {
  return new Promise((resolve) => {
    const child = spawn(binary, args, {
      cwd: options.cwd || APP_ROOT,
      windowsHide: true
    });
    let stdout = "";
    let stderr = "";
    child.stdout.on("data", (chunk) => {
      stdout += chunk.toString("utf8");
      if (options.onStdout) options.onStdout(chunk.toString("utf8"));
    });
    child.stderr.on("data", (chunk) => {
      stderr += chunk.toString("utf8");
      if (options.onStderr) options.onStderr(chunk.toString("utf8"));
    });
    child.on("error", (error) => resolve({ code: 1, stdout, stderr: `${stderr}\n${error.message}`.trim() }));
    child.on("close", (code) => resolve({ code, stdout, stderr }));
  });
}

function mediaToolsReady() {
  return fs.existsSync(FFMPEG) && fs.existsSync(FFPROBE);
}

async function ensureRemixMediaTools() {
  FFMPEG = resolveMediaTool("ffmpeg");
  FFPROBE = resolveMediaTool("ffprobe");
  if (mediaToolsReady()) {
    remixEngine.setMediaTools?.({ ffmpeg: FFMPEG, ffprobe: FFPROBE });
    return { ffmpeg: FFMPEG, ffprobe: FFPROBE, installed: true };
  }
  if (mediaToolInstallInFlight) return mediaToolInstallInFlight;
  mediaToolInstallInFlight = (async () => {
    if (!fs.existsSync(MEDIA_RUNTIME_NODE) || !fs.existsSync(MEDIA_RUNTIME_NPM)) {
      throw new Error("工作站缺少混剪运行组件安装器，请先在线更新到最新版本");
    }
    await fsp.mkdir(MEDIA_RUNTIME_ROOT, { recursive: true });
    const install = await runProcess(MEDIA_RUNTIME_NODE, [
      MEDIA_RUNTIME_NPM,
      "install",
      "--prefix", MEDIA_RUNTIME_ROOT,
      "@ffmpeg-installer/ffmpeg@1.1.0",
      "@ffprobe-installer/ffprobe@2.1.2",
      "--registry", "https://registry.npmjs.org",
      "--no-audit",
      "--no-fund"
    ], { cwd: APP_ROOT });
    if (install.code !== 0) {
      throw new Error(`混剪运行组件自动安装失败：${String(install.stderr || install.stdout || "网络或安装权限异常").trim()}`);
    }
    FFMPEG = resolveMediaTool("ffmpeg");
    FFPROBE = resolveMediaTool("ffprobe");
    if (!mediaToolsReady()) throw new Error("混剪运行组件安装完成，但未找到 FFmpeg/FFprobe，请重新打开工作站后重试");
    remixEngine.setMediaTools?.({ ffmpeg: FFMPEG, ffprobe: FFPROBE });
    return { ffmpeg: FFMPEG, ffprobe: FFPROBE, installed: true };
  })();
  try {
    return await mediaToolInstallInFlight;
  } finally {
    mediaToolInstallInFlight = null;
  }
}

function openFolder(folder) {
  return new Promise((resolve, reject) => {
    const opener = process.platform === "win32" ? "explorer.exe" : process.platform === "darwin" ? "open" : "xdg-open";
    const child = spawn(opener, [folder], {
      windowsHide: true,
      detached: true,
      stdio: "ignore"
    });
    child.on("error", reject);
    child.on("spawn", () => {
      child.unref();
      resolve();
    });
  });
}

function openFile(filePath) {
  return new Promise((resolve, reject) => {
    let child;
    if (process.platform === "win32") {
      const escaped = String(filePath || "").replace(/'/g, "''");
      child = spawn("powershell.exe", [
        "-NoProfile", "-NonInteractive", "-Command",
        `Start-Process -FilePath '${escaped}'`
      ], { windowsHide: true, detached: true, stdio: "ignore" });
    } else {
      const opener = process.platform === "darwin" ? "open" : "xdg-open";
      child = spawn(opener, [filePath], { detached: true, stdio: "ignore" });
    }
    child.on("error", reject);
    child.on("spawn", () => {
      child.unref();
      resolve();
    });
  });
}

function parseJsonDocuments(text) {
  const source = String(text || "");
  const documents = [];
  let start = -1;
  let stack = [];
  let inString = false;
  let escaped = false;
  for (let index = 0; index < source.length; index += 1) {
    const char = source[index];
    if (start < 0) {
      if (char === "{" || char === "[") {
        start = index;
        stack = [char];
        inString = false;
        escaped = false;
      }
      continue;
    }
    if (inString) {
      if (escaped) escaped = false;
      else if (char === "\\") escaped = true;
      else if (char === '"') inString = false;
      continue;
    }
    if (char === '"') {
      inString = true;
      continue;
    }
    if (char === "{" || char === "[") stack.push(char);
    if (char === "}" || char === "]") {
      const expected = char === "}" ? "{" : "[";
      if (stack.at(-1) !== expected) {
        start = -1;
        stack = [];
        continue;
      }
      stack.pop();
      if (!stack.length) {
        try {
          documents.push(JSON.parse(source.slice(start, index + 1)));
        } catch {
          // Continue scanning: CLI output can contain progress text around JSON documents.
        }
        start = -1;
      }
    }
  }
  return documents;
}

function tryParseJson(text) {
  try {
    return JSON.parse(text);
  } catch {
    const documents = parseJsonDocuments(text);
    return documents.length ? documents.at(-1) : null;
  }
}

function mp4Values(value) {
  const values = Array.isArray(value) ? value : value ? [value] : [];
  return values.map((item) => String(item || "").trim()).filter((item) => /^https?:\/\/.+\.mp4(?:\?.*)?$/i.test(item));
}

function extractMp4(text, excludedUrls = []) {
  const excluded = new Set((Array.isArray(excludedUrls) ? excludedUrls : [excludedUrls]).map((item) => String(item || "").trim()).filter(Boolean));
  const documents = parseJsonDocuments(String(text || ""));
  for (let index = documents.length - 1; index >= 0; index -= 1) {
    const document = documents[index] || {};
    const candidates = [
      ...mp4Values(document?.data?.url),
      ...mp4Values(document?.result?.data?.url),
      ...mp4Values(document?.reactFlowNode?.data?.url)
    ];
    const output = candidates.find((url) => !excluded.has(url));
    if (output) return output;
  }
  const matches = String(text || "").match(/https?:\/\/[^"\s]+\.mp4(?:\?[^"\s]*)?/g) || [];
  const usable = matches.filter((url) => !excluded.has(url));
  return usable.find((url) => /\/sd-gen-save-img\/|\/generated?\//i.test(url)) || usable[0] || "";
}

function explainLibtvFailure(result, fallback) {
  const text = `${result?.stderr || ""}\n${result?.stdout || ""}`;
  const apiCode = text.match(/code:\s*(\d+)/)?.[1] || text.match(/接口错误\s*\[(\d+)\]/)?.[1] || "";
  const apiMessage = text.match(/msg:\s*'([^']+)'/)?.[1] || text.match(/接口错误\s*\[\d+\]:\s*(.+)/)?.[1]?.trim() || "";

  if (apiCode === "401" || /未登录/.test(text)) {
    return "LibTV CLI 未登录。";
  }

  if (apiCode === "10001" || /用户未授权/.test(text)) {
    return "LibTV 用户未授权。当前 CLI 登录账号没有这个 LibTV 空间的操作权限，或登录的团队账号不对；请重新登录/切换账号，并确认能打开当前 LibTV 链接里的空间。";
  }

  return `${fallback}：${apiMessage || text.trim() || "未知错误"}`;
}

function imageRank(file, product) {
  const name = path.basename(file);
  const priority = product?.imagePriority || [];
  const index = priority.findIndex((part) => name.includes(part));
  return index === -1 ? 1000 : index;
}

async function listImageFiles(imageDir, product = null) {
  const currentProduct = product || productForImageDir(imageDir);
  const entries = await fsp.readdir(imageDir, { withFileTypes: true });
  return entries
    .filter((entry) => entry.isFile())
    .map((entry) => path.join(imageDir, entry.name))
    .filter((file) => IMAGE_FILE_PATTERN.test(file))
    .sort((a, b) => imageRank(a, currentProduct) - imageRank(b, currentProduct) || a.localeCompare(b, "zh-Hans-CN"));
}

async function resolveSceneImage(sceneImagePath) {
  const filePath = path.resolve(String(sceneImagePath || ""));
  if (!sceneImagePath) throw new Error("请选择场景图文件");
  if (!IMAGE_FILE_PATTERN.test(filePath)) throw new Error("场景图仅支持 png、jpg、jpeg、webp");
  let stat;
  try {
    stat = await fsp.stat(filePath);
  } catch {
    throw new Error(`场景图不存在：${filePath}`);
  }
  if (!stat.isFile()) throw new Error(`场景图必须是单个图片文件：${filePath}`);
  return filePath;
}

async function listVideoFiles(sourcePath) {
  const resolved = path.resolve(String(sourcePath || ""));
  if (!sourcePath) throw new Error("请选择原始视频文件或文件夹");
  let stat;
  try {
    stat = await fsp.stat(resolved);
  } catch {
    throw new Error(`原始视频路径不存在：${resolved}`);
  }
  if (stat.isFile()) {
    if (!VIDEO_FILE_PATTERN.test(resolved)) throw new Error("原始视频仅支持 mp4、mov、m4v、webm");
    return [resolved];
  }
  if (!stat.isDirectory()) throw new Error(`原始视频路径不可用：${resolved}`);
  const entries = await fsp.readdir(resolved, { withFileTypes: true });
  return entries
    .filter((entry) => entry.isFile() && VIDEO_FILE_PATTERN.test(entry.name))
    .map((entry) => path.join(resolved, entry.name))
    .sort((a, b) => path.basename(a).localeCompare(path.basename(b), "zh-Hans-CN", { numeric: true }));
}

async function resolveSourceVideos(config) {
  if (Array.isArray(config.sourceVideoPaths) && config.sourceVideoPaths.length) {
    const files = [];
    for (const sourcePath of config.sourceVideoPaths) {
      const resolved = path.resolve(sourcePath);
      if (!VIDEO_FILE_PATTERN.test(resolved)) throw new Error(`原始视频格式不支持：${path.basename(resolved)}`);
      let stat;
      try {
        stat = await fsp.stat(resolved);
      } catch {
        throw new Error(`原始视频不存在：${resolved}`);
      }
      if (!stat.isFile()) throw new Error(`原始视频必须是文件：${resolved}`);
      files.push(resolved);
    }
    return files;
  }
  if (config.sourceVideoPath) return listVideoFiles(config.sourceVideoPath);
  return [];
}

function ffmpegConcatListLine(filePath) {
  return `file '${path.resolve(filePath).replace(/\\/g, "/").replace(/'/g, "'\\''")}'`;
}

async function combineReferenceVideos(sourcePaths, outputDir, options = {}) {
  const sources = Array.isArray(sourcePaths) ? sourcePaths.map((item) => path.resolve(String(item || ""))).filter(Boolean) : [];
  if (sources.length < 2) throw new Error("完整参考视频至少需要2条碎镜头");
  if (sources.length > MAX_COMBINED_REFERENCE_CLIPS) throw new Error(`完整参考视频最多支持${MAX_COMBINED_REFERENCE_CLIPS}条碎镜头`);
  await ensureRemixMediaTools();
  const referenceDir = path.join(path.resolve(outputDir), "_reference_video");
  const normalizedDir = path.join(referenceDir, "normalized");
  await fsp.mkdir(normalizedDir, { recursive: true });
  const normalizedPaths = [];
  const clips = [];
  const names = Array.isArray(options.sourceNames) ? options.sourceNames : [];

  for (let index = 0; index < sources.length; index += 1) {
    const sourcePath = sources[index];
    const sourceProbe = await runProcess(FFPROBE, [
      "-v", "error",
      "-show_entries", "stream=codec_type,width,height:format=duration",
      "-of", "json",
      sourcePath
    ]);
    const sourceMedia = tryParseJson(sourceProbe.stdout);
    const sourceStream = sourceMedia?.streams?.find((stream) => stream.codec_type === "video");
    const sourceAudioStream = sourceMedia?.streams?.find((stream) => stream.codec_type === "audio");
    const sourceDuration = Number(sourceMedia?.format?.duration || 0);
    if (sourceProbe.code !== 0 || !sourceStream || !(sourceDuration > 0)) {
      throw new Error(`第${index + 1}条碎镜头无法读取或没有有效视频流：${path.basename(sourcePath)}\n${sourceProbe.stderr || sourceProbe.stdout}`);
    }
    const normalizedPath = path.join(normalizedDir, `${String(index + 1).padStart(2, "0")}-${safeName(path.basename(sourcePath, path.extname(sourcePath)))}.mp4`);
    const normalizedInputArgs = ["-i", sourcePath];
    if (!sourceAudioStream) {
      normalizedInputArgs.push("-f", "lavfi", "-t", sourceDuration.toFixed(6), "-i", "anullsrc=channel_layout=stereo:sample_rate=48000");
    }
    const normalized = await runProcess(FFMPEG, [
      "-hide_banner", "-loglevel", "error", "-y",
      ...normalizedInputArgs,
      "-map", "0:v:0",
      "-map", sourceAudioStream ? "0:a:0" : "1:a:0",
      "-vf", "scale=720:1280:force_original_aspect_ratio=decrease,pad=720:1280:(ow-iw)/2:(oh-ih)/2:color=black,setsar=1,fps=30",
      "-af", "aresample=async=1:first_pts=0,apad",
      "-c:v", "libx264",
      "-preset", "fast",
      "-crf", "22",
      "-pix_fmt", "yuv420p",
      "-c:a", "aac",
      "-b:a", "160k",
      "-ar", "48000",
      "-ac", "2",
      "-t", sourceDuration.toFixed(6),
      "-movflags", "+faststart",
      normalizedPath
    ]);
    if (normalized.code !== 0) {
      throw new Error(`第${index + 1}条碎镜头标准化失败：${path.basename(sourcePath)}\n${normalized.stderr || normalized.stdout}`);
    }
    normalizedPaths.push(normalizedPath);
    clips.push({
      index: index + 1,
      name: String(names[index] || path.basename(sourcePath)),
      sourcePath,
      normalizedPath,
      sourceDuration,
      sourceWidth: Number(sourceStream.width || 0),
      sourceHeight: Number(sourceStream.height || 0),
      sourceHadAudio: Boolean(sourceAudioStream)
    });
  }

  const concatListPath = path.join(referenceDir, "concat-order.txt");
  await fsp.writeFile(concatListPath, normalizedPaths.map(ffmpegConcatListLine).join("\n"), "utf8");
  const outputPath = path.join(referenceDir, `${safeName(options.outputName || "完整碎镜头参考视频")}.mp4`);
  const combined = await runProcess(FFMPEG, [
    "-hide_banner", "-loglevel", "error", "-y",
    "-f", "concat", "-safe", "0", "-i", concatListPath,
    "-c", "copy",
    "-movflags", "+faststart",
    outputPath
  ]);
  if (combined.code !== 0) throw new Error(`碎镜头拼接失败：${combined.stderr || combined.stdout}`);

  const outputProbe = await runProcess(FFPROBE, [
    "-v", "error",
    "-show_entries", "stream=codec_type,codec_name,width,height,r_frame_rate,pix_fmt,sample_rate,channels:format=duration,size",
    "-of", "json",
    outputPath
  ]);
  const outputMedia = tryParseJson(outputProbe.stdout);
  const outputStream = outputMedia?.streams?.find((stream) => stream.codec_type === "video");
  const outputAudioStream = outputMedia?.streams?.find((stream) => stream.codec_type === "audio");
  const duration = Number(outputMedia?.format?.duration || 0);
  const size = Number(outputMedia?.format?.size || 0);
  if (outputProbe.code !== 0 || !outputStream || !outputAudioStream || !(duration > 0)) {
    throw new Error(`完整参考视频校验失败：${outputProbe.stderr || outputProbe.stdout}`);
  }
  if (size > MAX_VIDEO_UPLOAD_BYTES) throw new Error(`完整参考视频超过${formatBytes(MAX_VIDEO_UPLOAD_BYTES)}，请减少碎镜头数量或时长`);
  return {
    outputPath,
    concatListPath,
    clipCount: clips.length,
    clips,
    duration,
    size,
    width: Number(outputStream.width || 0),
    height: Number(outputStream.height || 0),
    frameRate: String(outputStream.r_frame_rate || ""),
    codec: String(outputStream.codec_name || ""),
    pixelFormat: String(outputStream.pix_fmt || ""),
    audioCodec: String(outputAudioStream.codec_name || ""),
    audioSampleRate: Number(outputAudioStream.sample_rate || 0),
    audioChannels: Number(outputAudioStream.channels || 0),
    sourceAudioClipCount: clips.filter((clip) => clip.sourceHadAudio).length,
    audioPreserved: true,
    audioRemoved: false
  };
}

function formatBytes(bytes) {
  const value = Number(bytes || 0);
  if (value >= 1024 * 1024) return `${(value / 1024 / 1024).toFixed(2)}MB`;
  if (value >= 1024) return `${(value / 1024).toFixed(1)}KB`;
  return `${value}B`;
}

async function optimizeImageForUpload(sourcePath, uploadDir, index) {
  await ensureRemixMediaTools();
  await fsp.mkdir(uploadDir, { recursive: true });
  const originalBytes = (await fsp.stat(sourcePath)).size;
  const probe = await runProcess(FFPROBE, [
    "-v", "error",
    "-select_streams", "v:0",
    "-show_entries", "stream=width,height",
    "-of", "json",
    sourcePath
  ]);
  const stream = tryParseJson(probe.stdout)?.streams?.[0];
  const width = Number(stream?.width || 0);
  const height = Number(stream?.height || 0);
  if (probe.code !== 0 || !width || !height) {
    throw new Error(`无法读取图片尺寸，请确认FFprobe可用：${path.basename(sourcePath)}\n${probe.stderr || probe.stdout}`);
  }
  if (Math.max(width, height) <= UPLOAD_IMAGE_MAX_EDGE && originalBytes <= UPLOAD_IMAGE_MAX_BYTES) {
    return {
      sourcePath,
      uploadPath: sourcePath,
      processed: false,
      width,
      height,
      originalBytes,
      outputWidth: width,
      outputHeight: height,
      outputBytes: originalBytes
    };
  }

  const outputName = `upload-${String(index + 1).padStart(2, "0")}-${safeName(path.basename(sourcePath, path.extname(sourcePath)))}.jpg`;
  const outputPath = path.join(uploadDir, outputName);
  const quality = Math.max(50, Math.min(98, Math.floor(UPLOAD_IMAGE_JPEG_QUALITY)));
  const primaryQscale = Math.max(2, Math.min(12, Math.round((100 - quality) / 3)));
  const convert = async (maxEdge, qscale) => {
    const scaleFilter = `scale=w='min(${maxEdge},iw)':h='min(${maxEdge},ih)':force_original_aspect_ratio=decrease`;
    const filter = `[0:v]${scaleFilter},format=rgba,split=2[fg][bg];[bg]drawbox=color=white@1:t=fill[base];[base][fg]overlay=format=auto,format=rgb24[out]`;
    return runProcess(FFMPEG, [
      "-y", "-i", sourcePath,
      "-filter_complex", filter,
      "-map", "[out]",
      "-q:v", String(qscale),
      "-frames:v", "1",
      outputPath
    ]);
  };

  let conversion = await convert(UPLOAD_IMAGE_MAX_EDGE, primaryQscale);
  if (conversion.code !== 0) throw new Error(`图片上传前处理失败：${path.basename(sourcePath)}\n${conversion.stderr || conversion.stdout}`);
  let outputBytes = (await fsp.stat(outputPath)).size;
  if (outputBytes > UPLOAD_IMAGE_MAX_BYTES) {
    conversion = await convert(Math.min(1536, UPLOAD_IMAGE_MAX_EDGE), Math.min(15, primaryQscale + 2));
    if (conversion.code !== 0) throw new Error(`图片二次压缩失败：${path.basename(sourcePath)}\n${conversion.stderr || conversion.stdout}`);
    outputBytes = (await fsp.stat(outputPath)).size;
  }
  if (outputBytes > UPLOAD_IMAGE_MAX_BYTES) throw new Error(`图片压缩后仍超过${formatBytes(UPLOAD_IMAGE_MAX_BYTES)}：${path.basename(sourcePath)}`);
  const outputProbe = await runProcess(FFPROBE, [
    "-v", "error",
    "-select_streams", "v:0",
    "-show_entries", "stream=width,height",
    "-of", "json",
    outputPath
  ]);
  const outputStream = tryParseJson(outputProbe.stdout)?.streams?.[0];
  const outputWidth = Number(outputStream?.width || 0);
  const outputHeight = Number(outputStream?.height || 0);
  if (outputProbe.code !== 0 || !outputWidth || !outputHeight) {
    throw new Error(`压缩图片媒体校验失败：${path.basename(sourcePath)}\n${outputProbe.stderr || outputProbe.stdout}`);
  }
  return {
    sourcePath,
    uploadPath: outputPath,
    processed: true,
    width,
    height,
    originalBytes,
    outputWidth,
    outputHeight,
    outputBytes
  };
}

async function prepareUploadImages(job, imageFiles, uploadDir) {
  const prepared = [];
  let processedCount = 0;
  log(job, `上传前图片保护：长边超过 ${UPLOAD_IMAGE_MAX_EDGE}px 或文件超过 ${formatBytes(UPLOAD_IMAGE_MAX_BYTES)} 时，会生成临时压缩图上传；原图不会被修改`);
  for (let i = 0; i < imageFiles.length; i += 1) {
    const sourcePath = imageFiles[i];
    try {
      const item = await optimizeImageForUpload(sourcePath, uploadDir, i);
      prepared.push(item);
      if (item.processed) {
        processedCount += 1;
        log(job, `已生成临时上传图：${path.basename(sourcePath)} ${item.width}x${item.height} ${formatBytes(item.originalBytes)} -> ${item.outputWidth}x${item.outputHeight} ${formatBytes(item.outputBytes)}`);
      }
    } catch (error) {
      throw new Error(`图片上传前处理失败：${path.basename(sourcePath)}\n${error.message}`);
    }
  }
  if (processedCount) {
    log(job, `上传前图片保护完成：${processedCount}/${imageFiles.length} 张图片已使用临时压缩图`);
  } else {
    log(job, "上传前图片保护完成：所有图片均在安全尺寸内");
  }
  job.preparedImages = prepared.map((item) => ({
    sourcePath: item.sourcePath,
    uploadPath: item.uploadPath,
    processed: Boolean(item.processed),
    width: item.width || 0,
    height: item.height || 0,
    outputWidth: item.outputWidth || item.width || 0,
    outputHeight: item.outputHeight || item.height || 0,
    originalBytes: item.originalBytes || 0,
    outputBytes: item.outputBytes || item.originalBytes || 0
  }));
  return prepared.map((item) => item.uploadPath);
}

function renderStrategyText(value, variables) {
  return String(value || "")
    .replace(/\{scene\}/g, variables.scene)
    .replace(/\{purpose\}/g, variables.purpose)
    .replace(/\{productType\}/g, variables.productType);
}

function normalizeCoreScenes(coreScenes, variables) {
  if (!Array.isArray(coreScenes)) return [];
  return coreScenes
    .map((item) => {
      if (Array.isArray(item)) {
        return [
          renderStrategyText(item[0], variables),
          renderStrategyText(item[1], variables)
        ];
      }
      if (item && typeof item === "object") {
        return [
          renderStrategyText(item.coreElement || item.name || item.title, variables),
          renderStrategyText(item.sceneDetail || item.detail || item.prompt || item.description, variables)
        ];
      }
      return null;
    })
    .filter((item) => item && item[0] && item[1]);
}

function purposeSceneEntries(product, purpose) {
  const purposeScenes = product?.purposeScenes || {};
  const aliases = {
    "使用质地": "上手精华",
    "量感陈列": "囤货量感",
    "送礼属性": "送礼套装",
    "真实开箱": "真实开箱",
    "冰感功效": "冰感舒缓"
  };
  const key = purposeScenes[purpose] ? purpose : aliases[purpose];
  return Array.isArray(purposeScenes[key]) ? purposeScenes[key] : [];
}

function sceneTemplateText(item) {
  if (Array.isArray(item)) return String(item[1] || "");
  if (item && typeof item === "object") {
    return String(item.sceneDetail || item.detail || item.prompt || item.description || "");
  }
  return "";
}

function productPurposeScenes(product, purpose, variables) {
  const entries = purposeSceneEntries(product, purpose);
  const requestedScene = String(variables?.scene || "").trim();
  const defaultScene = String(product?.defaultScene || "").trim();
  const customScene = Boolean(requestedScene && defaultScene && requestedScene !== defaultScene);
  const compatibleEntries = customScene
    ? entries.filter((item) => /\{scene\}/.test(sceneTemplateText(item)))
    : entries;
  return normalizeCoreScenes(compatibleEntries, variables);
}

function productShotCount(index) {
  return index % 2 === 0 ? 2 : 1;
}

function productShotPlan(shotCount) {
  if (shotCount === 2) {
    return "本条使用2个连贯机位：前半段用中近景建立产品、手部、承载面和动作起点；只在动作自然承接点进行一次动作匹配切换，后半段用稍近或轻微侧向机位继续同一动作直至结果。第二机位不能让动作重新开始，产品位置、手部姿态、液体状态、光线方向、背景道具和空间轴线必须与第一机位连续。";
  }
  return "本条使用1个连续机位：从动作起点到结果保持同一机位关系，只允许一次极慢推近、轻微侧移或自然转焦，不能插入第二动作或另一处场景。";
}

function productTaskDisplayName(task = {}) {
  return String(task.displayName || task.sourceVideoName || task.coreElement || "产品镜任务").trim();
}

function productControlPrompt(product, purpose) {
  const configuredControl = String(product?.controlPrompt || "").trim();
  const profileControl = product?.productProfile ? [
    `统一产品资料卡版本：${PRODUCT_PROFILE_SCHEMA_VERSION}；正式产品名=${product.productProfile.formalName}；平台显示名=${product.productProfile.platformName}；规格=${product.productProfile.specification}。`,
    formatProductScaleReference(product.id),
    `产品数量策略：${formatProductQuantityStrategy(product.id)}。`,
    `产品状态顺序：${product.productProfile.openingStates.join("；")}。`,
    `产品内容物与结构：${product.productProfile.contentIdentity}。`
  ].join("\n") : "";
  if (product?.category !== "eye-mask") return [configuredControl, profileControl].filter(Boolean).join("\n");
  const needsMotionCue = /上手|精华|质地|开箱|开盖|达人|真实/.test(String(purpose || ""));
  const routeCue = needsMotionCue
    ? "动作参考按眼膜专控策略理解：一手稳定托住开口圆罐，另一手用短小白色弯头工具从单片下方托起；按需只选取片悬停、少量细丝或单滴、贴手背/前臂、指腹抚平、从边缘完整揭起中的一个简单动作，动作慢、干净、可辨，不要让手遮挡标签。"
    : "参考方式以产品图为主，强调包装露出、数量陈列、货架/收纳/礼盒布局和电商可投放构图。";
  return [
    configuredControl,
    profileControl,
    "眼膜专控：这是眼周护理眼膜产品，不是整片脸部面膜；画面中的单片必须是 under-eye patch / crescent-shaped gel eye mask patch，保持宽弧新月或肾形轮廓，外弧圆润、内弧凹入，一端宽圆、一端自然收窄且边缘连续完整。",
    "如果出现眼膜片，必须保持“罐内多片叠层与液体呈蓝绿色、单片离罐后接近无色透明”的关系；单片只有轻微冷色边缘与湿润水光，柔软厚润、受重力下垂但保持轮廓，不拉长、不破碎、不变成不透明亮蓝色胶片、黑色膜布或整脸面膜。",
    "线稿轮廓只作为形状约束概念，不允许画面出现黑线、描边、白底线稿、插画感或草图痕迹。",
    routeCue
  ].filter(Boolean).join("\n");
}

function productNegativePrompt(product) {
  if (product?.category !== "eye-mask") return "";
  return "整片脸部面膜，面膜纸，黑色膜布，石墨烯膜布，鼻贴，唇膜，不透明亮蓝色单片，圆片，矩形片，长条片，眼球特写，眼部手术，眼膜片拉长，眼膜片断裂，眼膜片变成随机胶片，十几条无限拉丝，工具刺穿眼贴，黑线描边，白底线稿，插画眼膜，手指变形，手指遮挡标签，额外说明文字";
}

function productEmotionContract(emotionHook) {
  return PRODUCT_EMOTION_HOOKS[emotionHook]?.prompt || PRODUCT_EMOTION_HOOKS[DEFAULTS.emotionHook].prompt;
}

function normalizeKnowledgeFramework(value) {
  const source = value && typeof value === "object" ? value : {};
  return {
    id: String(source.id || "").slice(0, 120),
    name: String(source.name || "").slice(0, 300),
    skeleton: String(source.skeleton || "").slice(0, 2000),
    description: String(source.description || "").slice(0, 2000),
    originalText: String(source.originalText || source.fullText || "").slice(0, 50000),
    category: String(source.category || "").slice(0, 200),
    productName: String(source.productName || "").slice(0, 300),
    evidenceTier: String(source.evidenceTier || "").slice(0, 40),
    source: String(source.source || "").slice(0, 100),
    sourceUrl: String(source.sourceUrl || "").slice(0, 4000)
  };
}

function knowledgeFrameworkRule(config = {}) {
  const framework = normalizeKnowledgeFramework(config.knowledgeFramework);
  if (!framework.id) return "";
  const original = framework.originalText
    ? `参考完整原文如下（用于保留语气、节奏和逻辑，不得照抄过期价格或跨SKU事实）：${framework.originalText}。`
    : "";
  return `部门文案经验已选定“${framework.name}”：成交骨架=${framework.skeleton || framework.description || "按已选框架执行"}。${original}只迁移抽象成交因果、叙事顺序和证据功能；产品事实、包装、价格、人物授权与合规仍以本任务已审核真值为准，不得照抄跨SKU事实。`;
}

